comms.text:
@1 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@2 מַלֵּל עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן קַדִּישִׁין תְּהוֹן אֲרֵי קַדִּישׁ אֲנָא יְיָ אֱלָהָכוֹן:
@3 גְּבַר מִן אִמֵּיהּ וּמִן אֲבוּהִי תְּהוֹן דָּחֲלִין וְיָת יוֹמֵי שַׁבַּיָּא דִילִי תִּטְרוּן אֲנָא יְיָ אֱלָהָכוֹן:
@4 לָא תִתְפְּנוּן בָּתַר טַעֲוָן וְדַחֲלָן דְּמַתְּכָא לָא תַעְבְּדוּן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@5 וַאֲרֵי תִכְּסוּן נִכְסַת קוּדְשַׁיָּא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְּסֻנֵּיהּ:
@6 בְּיוֹמָא דְיִתְנְכֵס יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר עַד יוֹמָא תְלִיתָאָה בְּנוּרָא יִתּוֹקָד:
@7 וְאִם אִתְאֲכָלָא יִתְאֲכֵל בְּיוֹמָא תְלִיתָאָה מְרָחָק הוּא לָא יְהֵי לְרַעֲוָא:
@8 וּדְיֵיכְלִנֵּיהּ חוֹבֵיהּ יְקַבֵּל אֲרֵי יָת קוּדְשָׁא דַיְיָ אַחֵל וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מְעַמֵּיהּ:
@9 וּבְמֶחְצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ לְמֶחְצָד וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵּט:
@10 וְכַרְמָךְ לָא תְעָלֵל וְנִתְרָא דְכַרְמָךְ לָא תְלַקֵּט לְעַנְיֵי וּלְגִיּוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@11 לָא תִּגְנְבוּן וְלָא תְכַדְּבוּן וְלָא תְשַׁקְּרוּן אֱנַשׁ בְּחַבְרֵיהּ:
@12 וְלָא תִשָּׁבְעוּן בִּשְׁמִי לְשִׁקְרָא וְתַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:
@13 לָא תַעֲשׁוֹק יָת חַבְרָךְ וְלָא תְאַנֵּס לָא תְבִית אַגְרָא דַאֲגִירָא לְוָתָךְ עַד צַפְרָא:
@14 לָא תְלוּט דְּלָא שָׁמַע וְקֳדָם דְּלָא חָזֵי לָא תְשִׂים תַּקְלָא וְתִדְחַל מֵאֱלָהָךְ אֲנָא יְיָ:
@15 לָא תַעְבְּדוּן שְׁקַר בְּדִינָא לָא תִסַּב אַפֵּי מַסְכֵּנָא וְלָא תֶהְדַּר אַפֵּי רַבָּא בְּקוּשְׁטָא תְּדִינֵיהּ לְחַבְרָךְ:
@16 לָא תֵיכוּל קוּרְצִין בְּעַמָּךְ לָא תְקוּם עַל דְּמָא דְחַבְרָךְ אֲנָא יְיָ:
@17 לָא תִשְׂנֵי יָת אֲחוּךְ בְּלִבָּךְ אוֹכָחָא תוֹכַח יָת חַבְרָךְ וְלָא תְקַבֵּל עַל דִּי לֵיהּ חוֹבָא:
@18 לָא תִקּוֹם וְלָא תִטַּר דְּבָבוּ לִבְנֵי עַמָּךְ וּתְרַחֵם לְחַבְרָךְ כְּוָתָךְ אֲנָא יְיָ:
@19 יָת קְיָמַי תִּטְּרוּן בְּעִירָךְ לָא תַרְכֵּב עֵרוּבִין חַקְלָךְ לָא תִזְרַע עֵרוּבִין וּלְבוּשׁ עֵרוּבִין שַׁעַטְנֵזָא לָא יִסַּק עֲלָךְ:
@20 וּגְבַר אֲרֵי יִשְׁכּוּב עִם אִתְּתָא שִׁכְבַת זַרְעָא וְהִיא אַמְתָא אֲחִידָא לִגְבַר וְאִתְפְּרָקָא לָא אִתְפְּרִיקַת בְּכַסְפָּא אוֹ חֵרוּתָא לָא אִתְיְהִיבַת לַהּ בִּשְׁטָר בִּקֻּרְתָּא תְהֵי לָא יוּמְתוּן אֲרֵי לָא אִתְחָרָרַת:
@21 וְיַיְתִי יָת אַשְׁמֵיהּ קֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא דְּכַר לַאֲשָׁמָא:
@22 וִיכַפֵּר עֲלוֹהִי כַהֲנָא בְּדִכְרָא דַאֲשָׁמָא קֳדָם יְיָ עַל חוֹבְתֵיהּ דִּי חָב וְיִשְׁתְּבֵק לֵיהּ מֵחוֹבְתֵיהּ דִּי חָב:
@23 וַאֲרֵי תֵעֲלוּן לְאַרְעָא וְתִצְּבוּן כָּל אִלַּן דְּמֵיכַל וּתְרַחֲקוּן רָחָקָא יָת אִבֵּיהּ תְּלַת שְׁנִין יְהֵי לְכוֹן מְרָחָק לַאֲבָדָא לָא יִתְאֲכֵל:
@24 וּבְשַׁתָּא רְבִיעֵתָא יְהֵי כָּל אִבֵּיהּ קֹדֶשׁ תֻּשְׁבְּחָן קֳדָם יְיָ:
@25 וּבְשַׁתָּא חֲמִשֵּׁתָא תֵּיכְלוּן יָת אִבֵּיהּ לְאוֹסָפָא לְכוֹן עֲלַלְתֵּיהּ אֲנָא יְיָ אֱלָהָכוֹן:
@26 לָא תֵיכְלוּן עַל דְּמָא לָא תְנַחֲשׁוּן וְלָא תְעוֹנוּן:
@27 לָא תַקְּפוּן פָּאתָא דְרֵישְׁכוֹן וְלָא תְחַבֵּל יָת פָּאתָא דְדִקְנָךְ:
@28 וְחִבּוּל עַל מִית לָא תִתְּנוּן בְּבִסְרְיכוֹן וְרוּשְׁמִין חֲרִיתִין לָא תִתְּנוּן בְּכוֹן אֲנָא יְיָ:
@29 לָא תַחֵל יָת בְּרַתָּךְ לְאַטְעֲיוּתַהּ וְלָא תִטְעֵי אַרְעָא וְתִתְמְלֵי אַרְעָא עֵצַת חִטְאִין:
@30 יָת יוֹמֵי שַׁבַּיָּא דִילִי תִּטְרוּן וּלְבֵית מַקְדְּשִׁי תְּהוֹן דַּחֲלִין אֲנָא יְיָ:
@31 לָא תִתְפְּנוּן בָּתַר בִּדִּין וּדְכוּרוּ לָא תִתְבְּעוּן לְאִסְתָּאָבָא בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@32 מִן קֳדָם דְּסַבַּר בְּאוֹרַיְתָא תְּקוּם וּתְהַדַּר אַפֵּי סָבָא וְתִדְחַל מֵאֱלָהָךְ אֲנָא יְיָ:
@33 וַאֲרֵי יִתְגַּיַּר עִמָּךְ גִּיּוֹרָא בְּאַרְעֲכוֹן לָא תוֹנוּן יָתֵיהּ:
@34 כְּיַצִּיבָא מִנְּכוֹן יְהֵי לְכוֹן גִּיּוֹרָא דְּיִתְגַּיַּר בֵּינֵיכוֹן וּתְרַחֵם לֵיהּ כְּוָתָךְ אֲרֵי דַיָּרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהָכוֹן:
@35 לָא תַעְבְּדוּן שְׁקַר בְּדִין בִּמְשַׁחְתָּא בְּמַתְקְלָא וּבִמְכִלְתָּא:
@36 מֹאזְנָוָן דִּקְשׁוֹט מַתְקְלָן דִּקְשׁוֹט מְכִילָן דִּקְשׁוֹט וְהִינִין דִּקְשׁוֹט יְהוֹן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן דִּי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@37 וְתִטְּרוּן יָת כָּל קְיָמַי וְיָת כָּל דִּינַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא יְיָ:
@38 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@39 וְעִם בְּנֵי יִשְׂרָאֵל תֵּימַר גְּבַר גְּבַר מִבְּנֵי יִשְׂרָאֵל וּמִין גִּיּוֹרָא דְּיִתְגַּיְרוּן בְּיִשְׂרָאֵל דִּי יִתֵּן מִזַּרְעֵיהּ לְמוֹלֶךְ אִתְקְטָלָא יִתְקְטֵל עַמָּא בֵית יִשְׂרָאֵל יִרְגְּמֻנֵּיהּ בְּאַבְנָא:
@40 וַאֲנָא אֶתֵּן יָת רוּגְזִי בְּגַבְרָא הַהוּא וֶאֱשֵׁיצֵי יָתֵיהּ מִגּוֹ עַמֵּיהּ אֲרֵי מִזַּרְעֵיהּ יְהַב לְמוֹלֶךְ בְּדִיל לְסָאֲבָא יָת מַקְדְּשִׁי וּלְאַחַלָּא יָת שְׁמָא דְקוּדְשִׁי:
@41 וְאִם מִכְבַּשׁ יִכְבְּשׁוּן עַמָּא בֵית יִשְׂרָאֵל יָת עֵינֵיהוֹן מִן גַּבְרָא הַהוּא בִּדְיָהֵב מִזַּרְעֵיהּ לְמוֹלֶךְ בְּדִיל דְּלָא לְקַטָּלָא יָתֵיהּ:
@42 וֶאֱשַׁוֵּי אֲנָא יָת רוּגְזִי בְּגַבְרָא הַהוּא וּבִסְעָדוֹהִי וֶאֱשֵׁיצֵי יָתֵיהּ וְיָת כָּל דְּטָעָן בַּתְרוֹהִי לְמִטְעֵי בָּתַר מוֹלֶךְ מִגּוֹ עַמְּהוֹן:
@43 וֶאֱנַשׁ דִּי יִתְפְּנֵי בָּתַר בִּדִּין וּדְכוּרוּ לְמִטְעֵי בַתְרֵיהוֹן וְאֶתֵּן יָת רוּגְזִי בַּאֲנָשָׁא הַהִיא וֶאֱשֵׁיצֵי יָתֵיהּ מִגּוֹ עַמֵּיהּ:
@44 וְתִתְקַדְּשׁוּן וּתְהוֹן קַדִּישִׁין אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@45 וְתִטְּרוּן יָת קְיָמַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא יְיָ מְקַדִּשְׁכוֹן:
@46 אֲרֵי גְבַר גְּבַר דִּי יְלוּט יָת אֲבוּהִי וְיָת אִמֵּיהּ אִתְקְטָלָא יִתְקְטֵל אֲבוּהִי וְאִמֵּיהּ לַט קְטָלָא חַיָּב:
@47 וּגְבַר דִּי יְגוּף יָת אִתַּת גְּבַר דִּי יְגוּף יָת אִתַּת חַבְרֵיהּ אִתְקְטָלָא יִתְקְטֵל גַּיָּפָא וְגַיַּפְתָּא:
@48 וּגְבַר דִּי יִשְׁכּוּב עִם אִתַּת אֲבוּהִי עֶרְיְתָא דַאֲבוּהִי גַּלִּי אִתְקְטָלָא יִתְקַטְּלוּן תַּרְוֵיהוֹן קְטָלָא חַיָּבִין:
@49 וּגְבַר דִּי יִשְׁכּוּב יָת כַּלְּתֵיהּ אִתְקְטָלָא יִתְקַטְּלוּן תַּרְוֵיהוֹן תִּבְלָא עֲבָדוּ קְטָלָא חַיָּבִין:
@50 וּגְבַר דִּי יִשְׁכּוּב יָת דְּכוּרָא מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא עֲבָדוּ תַּרְוֵיהוֹן אִתְקְטָלָא יִתְקַטְּלוּן קְטָלָא חַיָּבִין:
@51 וּגְבַר דִּי יִסַּב יָת אִתְּתָא וְיָת אִמַּהּ עֵצַת חִטְאִין הִיא בְּנוּרָא יוֹקְדוּן יָתֵיהּ וְיָתְהֶן וְלָא תְהֵי עֵצַת חִטְאִין בֵּינֵיכוֹן:
@52 וּגְבַר דִּי יִתֵּן שְׁכָבְתֵּיהּ בִּבְעִירָא אִתְקְטָלָא יִתְקְטֵל וְיָת בְּעִירָא תִּקְטְלוּן:
@53 וְאִתְּתָא דִּי תִקְרַב לְכָל בְּעִירָא לְמִשְׁלַט בַּהּ וְתִקְטוֹל יָת אִתְּתָא וְיָת בְּעִירָא אִתְקְטָלָא יִתְקַטְּלוּן קְטָלָא חַיָּבִין:
@54 וּגְבַר דִּי יִסַּב יָת אֲחָתֵיהּ בַּת אֲבוּהִי אוֹ בַת אִמֵּיהּ וְיֶחֱזֵי יָת עֶרְיְתַהּ וְהִיא תֶחֱזֵי יָת עֶרְיְתֵיהּ קְלָנָא הוּא וְיִשְׁתֵּיצוּן לְעֵינֵי בְּנֵי עַמְּהוֹן עֶרְיַת אֲחָתֵיהּ גַּלִּי חוֹבֵיהּ יְקַבֵּל:
@55 וּגְבַר דִּי יִשְׁכּוּב יָת אִתְּתָא סוֹאֲבָתָא וִיגַלִּי יָת עֶרְיְתַהּ יָת קְלָנַהּ גַּלִּי וְהִיא תְגַלֵּי יָת סוֹאֲבַת דְּמָהָא וְיִשְׁתֵּיצוּן תַּרְוֵיהוֹן מִגּוֹ עַמְּהוֹן:
@56 וְעֶרְיַת אֲחַת אִמָּךְ וַאֲחַת אָבוּךְ לָא תְגַלֵּי אֲרֵי יָת קָרִיבֵיהּ גַּלִּי חוֹבְהֶן יְקַבְּלוּן:
@57 וּגְבַר דִּי יִשְׁכּוּב יָת אִתַּת אַח אֲבוּהִי עֶרְיַת אַח אֲבוּהִי גַּלִּי חוֹבְהֶן יְקַבְּלוּן בְּלָא וְלָד יְמוּתוּן:
@58 וּגְבַר דִּי יִסַּב יָת אִתַּת אֲחוּהִי מְרָחָקָא הִיא עֶרְיְתָא דַאֲחוּהִי גַּלִּי בְּלָא וְלָד יְהוֹן:
@59 וְתִטְּרוּן יָת כָּל קְיָמַי וְיָת כָּל דִּינַי וְתַעְבְּדוּן יָתְהוֹן וְלָא תְרוֹקֵן יָתְכוֹן אַרְעָא דִּי אֲנָא מַעֵיל יָתְכוֹן תַּמָּן לְמִתַּב בַּהּ:
@60 וְלָא תְהָכוּן בְּנִימוֹסֵי עַמְמַיָּא דִּי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן אֲרֵי יָת כָּל אִלֵּין עֲבָדוּ וְרָחִיק מֵימְרִי יָתְהוֹן:
@61 וַאֲמָרִית לְכוֹן אַתּוּן תִּירְתוּן יָת אַרְעֲהוֹן וַאֲנָא אֶתְּנִנַּהּ לְכוֹן לְמֵירַת יָתַהּ אַרְעָא עָבְדָא חֲלָב וּדְבָשׁ אֲנָא יְיָ אֱלָהָכוֹן דִּי אַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָּא:
@62 וְתַפְרְשׁוּן בֵּין בְּעִירָא דַכְיָא לִמְסָאָבָא וּבֵין עוֹפָא מְסָאָבָא לִדְכֵי וְלָא תְשַׁקְּצוּן יָת נַפְשָׁתֵיכוֹן בִּבְעִירָא וּבְעוֹפָא וּבְכֹל דִּי תַרְחֵשׁ אַרְעָא דִּי אַפְרֵשִׁית לְכוֹן לְסָאָבָא:
@63 וּתְהוֹן קֳדָמַי קַדִּישִׁין אֲרֵי קַדִּישׁ אֲנָא יְיָ וְאַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָּא לְמֶהֱוֵי פָלְחִין קֳדָמָי:
@64 וּגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵי בְהוֹן בִּדִּין אוֹ דְּכוּר אִתְקְטָלָא יִתְקַטְּלוּן בְּאַבְנָא יִרְגְּמוּן יָתְהוֹן קְטָלָא חַיָּבִין:

@2 **דבר אל כל עדת בני ישראל.** מְלַמֵּד שֶׁנֶּאֶמְרָה פָרָשָׁה זוֹ בְּהַקְהֵל מִפְּנֵי שֶׁרֹב גּוּפֵי תוֹרָה תְלוּיִּין בָּהּ (ספרא):
@2 **קדשים תהיו.** הֱווּ פְרוּשִׁים מִן הָעֲרָיוֹת וּמִן הָעֲבֵרָה, שֶׁכָּל מָקוֹם שֶׁאַתָּה מוֹצֵא גֶדֶר עֶרְוָה אַתָּה מוֹצֵא קְדֻשָּׁה, אִשָּׁה זֹנָה וַחֲלָלָה וְגוֹ' אֲנִי ה' מְקַדִּשְׁכֶם (ויקרא כ"א), וְלֹא יְחַלֵּל זַרְעוֹ, אֲנִי ה' מְקַדְּשׁוֹ (שם), קְדֹשִׁים יִהְיוּ, אִשָּׁה זֹנָה וַחֲלָלָה (שם):
@3 **איש אמו ואביו תיראו.** כָּל אֶחָד מִכֶּם תִּירְאוּ אָבִיו וְאִמּוֹ, זֶהוּ פְשׁוּטוֹ; וּמִדְרָשׁוֹ: אֵין לִי אֶלָּא אִישׁ, אִשָּׁה מִנַּיִן? כְּשֶׁהוּא אוֹמֵר תִּירָאוּ הֲרֵי כָאן שְׁנַיִם, אִם כֵּן לָמָּה נֶאֱמַר אִישׁ? שֶׁהָאִישׁ סֵפֶק בְּיָדוֹ לַעֲשׂוֹת אֲבָל אִשָּׁה רְשׁוּת אֲחֵרִים עָלֶיהָ (ספרא; קידושין ל'):
@3 **אמו ואביו תיראו.** כָּאן הִקְדִּים אֵם לָאָב, לְפִי שֶׁגָּלוּי לְפָנָיו שֶׁהַבֵּן יָרֵא אֶת אָבִיו יוֹתֵר מֵאִמּוֹ, וּבַכָּבוֹד הִקְדִּים אָב לָאֵם, לְפִי שֶׁגָּלוּי לְפָנָיו שֶׁהַבֵּן מְכַבֵּד אֶת אִמּוֹ יוֹתֵר מֵאָבִיו, מִפְּנֵי שֶׁמְּשַׁדַּלְתּוֹ בִדְבָרִים (שם):
@3 **ואת שבתתי תשמרו.** סָמַךְ שַׁבָּת לְמוֹרָא אָב, לוֹמַר אַף עַל פִּי שֶׁהִזְהַרְתִּיךָ עַל מוֹרָא אָב, אִם יֹאמַר לְךָ חַלֵּל אֶת הַשַּׁבָּת, אַל תִּשְׁמַע לוֹ, וְכֵן בִּשְׁאָר כָּל הַמִּצְווֹת (בבא מציעא ל"ב):
@3 **אני ה' אלהיכם.** אַתָּה וְאָבִיךָ חַיָּבִים בִּכְבוֹדִי, לְפִיכָךְ לֹא תִשְׁמַע לוֹ לְבַטֵּל אֶת דְּבָרַי. אֵיזֶהוּ מוֹרָא? לֹא יֵשֵׁב בִּמְקוֹמוֹ וְלֹא יְדַבֵּר בִּמְקוֹמוֹ וְלֹא יִסְתֹּר אֶת דְּבָרָיו, וְאֵיזֶהוּ כָבוֹד? מַאֲכִיל וּמַשְׁקֶה, מַלְבִּישׁ וּמַנְעִיל, מַכְנִיס וּמוֹצִיא (קידושין ל"א):
@4 **אל תפנו אל האלילם.** לְעָבְדָם; אֱלִילִים לְשׁוֹן אַל — כְּלֹא הוּא חָשׁוּב:
@4 **ואלהי מסכה.** תְּחִלָּתָן אֱלִילִים הֵם, וְאִם אַתָּה פוֹנֶה אַחֲרֵיהֶם סוֹפְךָ עוֹשֶׂה אוֹתָם אֱלוֹהוֹת (ספרא):
@4 **לא תעשו לכם.** לֹא תַעֲשׂוּ לַאֲחֵרִים וְלֹא אֲחֵרִים לָכֶם; וְאִם תֹּאמַר לֹא תַעֲשׂוּ לְעַצְמְכֶם אֲבָל אֲחֵרִים עוֹשִׂין לָכֶם, הֲרֵי כְבָר נֶאֱמַר לֹא יִהְיֶה לְךָ (שמות כ') — לֹא שֶׁלְּךָ וְלֹא שֶׁל אֲחֵרִים:
@5 **וכי תזבחו וגו'.** לֹא נֶאֶמְרָה פָרָשָׁה זוֹ אֶלָּא לְלַמֵּד, שֶׁלֹּא תְהֵא זְבִיחָתָן אֶלָּא עַל מְנָת לֵאָכֵל בְּתוֹךְ הַזְּמַן הַזֶּה, שֶׁאִם לִקְבֹּעַ לָהֶם זְמַן אֲכִילָה, הֲרֵי כְבָר נֶאֱמַר (ויקרא ז') וְאִם נֶדֶר אוֹ נְדָבָה זֶבַח קָרְבָּנוֹ וְגוֹ' (ספרא):
@5 **לרצנכם תזבחהו.** תְּחִלַּת זְבִיחָתוֹ תְּהֵא עַל מְנָת נַחַת רוּחַ — שֶׁיְּהֵא לָכֶם לְרָצוֹן, שֶׁאִם תְּחַשְּׁבוּ עָלָיו מַחֲשֶׁבֶת פְּסוּל לֹא יֵרָצֶה עֲלֵיכֶם לְפָנַי:
@5 **לרצנכם.** אפיי"צימנטו, זֶהוּ לְפִי פְשׁוּטוֹ; וְרַבּוֹתֵינוּ לָמְדוּ מִכָּאן לַמִּתְעַסֵּק בַּקֳּדָשִׁים שֶׁפָּסוּל, שֶׁצָּרִיךְ שֶׁיִּתְכַּוֵּן לִשְׁחֹט (זבחים מ"ז; חולין י"ג):
@6 **ביום זבחכם יאכל.** כְּשֶׁתִּזְבְּחוּהוּ תִּשְׁחֲטוּהוּ עַל מְנָת זְמַן זֶה שֶׁקָּבַעְתִּי לָכֶם כְּבָר:
@7 **ואם האכל יאכל וגו'.** אִם אֵינוֹ עִנְיָן לְחוּץ לִזְמַנּוֹ, שֶׁהֲרֵי כְבָר נֶאֱמַר וְאִם הֵאָכֹל יֵאָכֵל מִבְּשַׂר זֶבַח שְׁלָמָיו וְגוֹ' (ויקרא ז'), תְּנֵהוּ עִנְיָן לְחוּץ לִמְקוֹמוֹ; יָכוֹל יִהְיוּ חַיָּבִין כָּרֵת עַל אֲכִילָתוֹ, תַּ"לֹ וְהַנֶּפֶשׁ הָאֹכֶלֶת מִמֶּנּוּ עֲוֹנָהּ תִּשָּׂא, "מִמֶּנּוּ" וְלֹא מֵחֲבֵרוֹ, יָצָא הַנִּשְׁחָט בְּמַחֲשֶׁבֶת חוּץ לִמְקוֹמוֹ (זבחים כ"ח):
@7 **פגול.** מְתֹעָב, כְּמוֹ וּמְרַק פִּגֻּלִים כְּלֵיהֶם (ישעיהו ס"ה):
@8 **ואכליו עונו ישא.** בְּנוֹתָר גָּמוּר הַכָּתוּב מְדַבֵּר, וְאֵינוֹ עָנוּשׁ כָּרֵת עַל הַנִּשְׁחָט חוּץ לִמְקוֹמוֹ, שֶׁכְּבָר מִעֲטוֹ הַכָּתוּב, וְזֶה בְּנוֹתָר גָּמוּר מְדַבֵּר, וּבְמַסֶּכֶת כָּרֵתוֹת (דף ה'), לְמָדוּהוּ מִגְּזֵרָה שָׁוָה:
@9 **לא תכלה פאת שדך.** שֶׁיַּנִּיחַ פֵּאָה בְסוֹף שָׂדֵהוּ (עי' ספרא):
@9 **ולקט קצירך.** שִׁבֳּלִים הַנּוֹשְׁרִים בִּשְׁעַת קְצִירָה, אַחַת אוֹ שְׁתַּיִם, אֲבָל שָׁלוֹשׁ אֵינָן לֶקֶט (פאה פ"ו):
@10 **לא תעולל.** לֹא תִטֹּל עוֹלֵלוֹת שֶׁבָּהּ, וְהֵן נִכָּרוֹת; אֵיזֶהוּ עוֹלֵלוֹת? כֹּל שֶׁאֵין לוֹ לֹא כָתֵף וְלֹא נָטֵף (ספרא):
@10 **ופרט כרמך.** גַּרְגְּרֵי עֲנָבִים הַנּוֹשְׁרִים בִּשְׁעַת בְּצִירָה:
@10 **אני ה' אלהיכם.** דַּיָּן לִפָּרַע; וְאֵינִי גוֹבֶה מִכֶּם אֶלָּא נְפָשׁוֹת, שֶׁנֶּאֱמַר אַל תִּגְזָל דָּל וְגוֹ' כִּי ה' יָרִיב רִיבָם וְגוֹ' (משלי כ"ב):
@11 **לא תגנבו.** אַזְהָרָה לְגוֹנֵב מָמוֹן, אֲבָל לֹא תִגְנֹב שֶׁבַּעֲשֶׂרֶת הַדִּבְּרוֹת אַזְהָרָה לְגוֹנֵב נְפָשׁוֹת, דָּבָר הַלָּמֵד מֵעִנְיָנוֹ — דָּבָר שֶׁחַיָּבִין עָלָיו מִיתַת בֵּית דִּין:
@11 **ולא תכחשו.** לְפִי שֶׁנֶּאֱמַר (ויקרא ה'), וְכִחֶשׁ בָּהּ מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ, לָמַדְנוּ עֹנֶשׁ, אַזְהָרָה מִנַּיִן? תַּ"לֹ וְלֹא תְכַחֲשׁוּ:
@11 **ולא תשקרו.** לְפִי שֶׁנֶּאֱמַר (שם), וְנִשְׁבַּע עַל שָׁקֶר יְשַׁלֵּם קֶרֶן וְחֹמֶשׁ, לָמַדְנוּ עֹנֶשׁ, אַזְהָרָה מִנַּיִן? תַּ"ל וְלֹא תְשַׁקְּרוּ:
@11 **לא תגנבו ולא תכחשו ולא תשקרו ולא תשבעו.** אִם גָּנַבְתָּ סוֹפְךָ לְכַחֵשׁ, סוֹפְךָ לְשַׁקֵּר, סוֹפְךָ לִשָּׁבַע לַשֶּׁקֶר:
@12 **ולא תשבעו בשמי.** לָמָּה נֶאֱמַר? לְפִי שֶׁנֶּאֱמַר לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךָ לַשָּׁוְא (שמות כ'), יָכוֹל לֹא יְהֵא חַיָּב אֶלָּא עַל שֵׁם הַמְיֻחָד, מִנַּיִן לְרַבּוֹת כָּל הַכִּנּוּיִין? תַּ"ל וְלֹא תִשָּׁבְעוּ בִשְׁמִי לַשָּׁקֶר — כָּל שֵׁם שֶׁיֵּשׁ לִי (ספרא):
@13 **לא תעשק.** זֶה הַכּוֹבֵשׁ שְׂכַר שָׂכִיר (בבא מציעא ס"א):
@13 **לא תלין.** לְשׁוֹן נְקֵבָה, מוּסָב עַל הַפְּעוּלָה:
@13 **עד בקר.** בִּשְׂכִיר יוֹם הַכָּתוּב מְדַבֵּר, שֶׁיְּצִיאָתוֹ מִשֶּׁשָּׁקְעָה חַמָּה, לְפִיכָךְ זְמַן גִּבּוּי שְׂכָרוֹ כָּל הַלָּיְלָה, וּבְמָקוֹם אַחֵר הוּא אוֹמֵר וְלֹא תָבוֹא עָלָיו הַשֶּׁמֶשׁ (דברים כ"ד), מְדַבֵּר בִּשְֹכִיר לַיְלָה, שֶׁהַשְׁלָמַת פְּעֻלָּתוֹ מִשֶּׁיַּעֲלֶה עַמּוּד הַשַּׁחַר, לְפִיכָךְ זְמַן גִּבּוּי שְׂכָרוֹ כָּל הַיּוֹם, לְפִי שֶׁנָּתְנָה תוֹרָה זְמַן לְבַעַל הַבַּיִת עוֹנָה לְבַקֵּשׁ מָעוֹת (בבא מציעא ק"י):
@14 **לא תקלל חרש.** אֵין לִי אֶלָּא חֵרֵשׁ, מִנַּיִן לְרַבּוֹת כָּל אָדָם? תַּ"ל בְּעַמְּךָ לֹא תָאֹר (שמות כ"ב), אִם כֵּן לָמָּה נֶאֱמַר חֵרֵשׁ? מַה חֵרֵשׁ מְיֻחָד שֶׁהוּא בַחַיִּים, אַף כָּל שֶׁהוּא בַחַיִּים, יָצָא הַמֵּת שֶׁאֵינוֹ בַחַיִּים (ספרא):
@14 **ולפני עור לא תתן מכשול.** לִפְנֵי הַסּוּמָא בְדָבָר לֹא תִתֵּן עֵצָה שֶׁאֵינָהּ הוֹגֶנֶת לוֹ, אַל תֹּאמַר מְכֹר שָׂדְךָ וְקַח לְךָ חֲמוֹר, וְאַתָּה עוֹקֵף עָלָיו וְנוֹטְלָהּ הֵימֶנּוּ (שם):
@14 **ויראת מאלהיך.** לְפִי שֶׁהַדָּבָר הַזֶּה אֵינוֹ מָסוּר לַבְּרִיּוֹת לֵידַע אִם דַּעְתּוֹ שֶׁל זֶה לְטוֹבָה אוֹ לְרָעָה, וְיָכוֹל לְהִשָּׁמֵט וְלוֹמַר לְטוֹבָה נִתְכַּוַּנְתִּי, לְפִיכָךְ נֶאֱמַר בּוֹ וְיָרֵאתָ מֵּאֱלֹהֶיךָ הַמַּכִּיר מַחְשְׁבוֹתֶיךָ; וְכֵן כָּל דָּבָר הַמָּסוּר לְלִבּוֹ שֶׁל אָדָם הָעוֹשֵׂהוּ וְאֵין שְׁאָר הַבְּרִיּוֹת מַכִּירוֹת בּוֹ, נֶאֱמַר בּוֹ וְיָרֵאתָ מֵּאֱלֹהֶיךָ:
@15 **לא תעשו עול במשפט.** מְלַמֵּד שֶׁהַדַּיָּן הַמְקַלְקֵּל אֶת הַדִּין קָרוּי עַוָּל, שָׂנוּי וּמְשֻׁקָּץ, חֵרֶם וְתוֹעֵבָה, שֶׁהָעָוֶל קָרוּי תּוֹעֵבָה, שֶׁנֶּאֱמַר כִּי תוֹעֲבַת ה' וְגוֹ' כֹּל עֹשֵׂה עָוֶל (דברים כ"ה), וְהַתּוֹעֵבָה קְרוּיָה חֵרֶם וְשֶׁקֶץ שֶׁנֶּאֱמַר וְלֹא תָבִיא תוֹעֵבָה אֶל בֵּיתֶךָ וְהָיִיתָ חֵרֶם כָּמֹהוּ שַׁקֵּץ תְּשַׁקְּצֶנּוּ וְגוֹ' (שם ז'):
@15 **לא תשא פני דל.** שֶׁלֹּא תֹאמַר עָנִי הוּא זֶה, וְהֶעָשִׁיר חַיָּב לְפַרְנְסוֹ, אֲזַכֶּנּוּ בַדִּין וְנִמְצָא מִתְפַּרְנֵס בִּנְקִיּוּת (ספרא):
@15 **ולא תהדר פני גדול.** שֶׁלֹּא תֹאמַר עָשִׁיר הוּא זֶה, בֶּן גְּדוֹלִים הוּא זֶה, הֵיאַךְ אֲבַיְּשֶׁנּוּ וְאֶרְאֶה בְּבָשְׁתּוֹ? עֹנֶשׁ יֵשׁ בַּדָּבָר לְכָךְ נֶאֱמַר וְלֹא תֶהְדַּר פְּנֵי גָדוֹל:
@15 **בצדק תשפט עמיתך.** כְּמַשְׁמָעוֹ; דָּ"אַ: הֱוֵי דָן אֶת חֲבֵרְךָ לְכַף זְכוּת (שבועות ל'):
@16 **לא תלך רכיל.** אֲנִי אוֹמֵר עַל שֵׁם שֶׁכָּל מְשַׁלְּחֵי מְדָנִים וּמְסַפְּרֵי לָשׁוֹן הָרַע הוֹלְכִים בְּבָתֵּי רֵעֵיהֶם לְרַגֵּל מַה יִּרְאוּ רָע, אוֹ מַה יִּשְׁמְעוּ רָע, לְסַפֵּר בַּשּׁוּק, נִקְרָאִים הוֹלְכֵי רָכִיל — הוֹלְכֵי רְגִילָה, אשפיי"מנט בְּלַעַז. וּרְאָיָה לִדְבָרַי, שֶׁלֹּא מָצִינוּ רְכִילוּת שֶׁאֵין כָּתוּב בִּלְשׁוֹן הֲלִיכָה, לֹא תֵלֵךְ רָכִיל, הֹלְכֵי רָכִיל נְחֹשֶׁת וּבַרְזֶל (ירמיהו ו'), וּשְׁאָר לָשׁוֹן הָרַע אֵין כָּתוּב בּוֹ הֲלִיכָה, מְלָשְׁנִי בַסֵּתֶר רֵעֵהוּ (תהילים ק"א), לָשׁוֹן רְמִיָּה (שם ק"כ), לָשׁוֹן מְדַבֶּרֶת גְּדֹלוֹת (שם י"ב); לְכָךְ אֲנִי אוֹמֵר שֶׁהַלָּשׁוֹן הוֹלֵךְ וּמְרַגֵּל, שֶׁהַכַּ"ף נֶחֱלֶפֶת בְּגִימֶ"ל, שֶׁכָּל הָאוֹתִיּוֹת שֶׁמּוֹצָאֵיהֶם מִמָּקוֹם אֶחָד מִתְחַלְּפוֹת זוֹ בָזוֹ, בֵּי"ת בְּפֵ"א וְגִימֶ"ל בְּכַ"ף וְקוֹ"ף, וְנוּ"ן בְּלָמֶ"ד, וְזַיִ"ן בְּצָדִ"י, וְכֵן וַיְרַגֵּל בְּעַבְדְּךָ (שמואל ב י"ט) — רִגֵּל בְּמִרְמָה לֵאמֹר עָלַי רָעָה, וְכֵן לֹא רָגַל עַל לְשֹׁנוֹ (תהילים ט"ו), וְכֵן רוֹכֵל — הַסּוֹחֵר וּמְרַגֵּל אַחַר כָּל סְחוֹרָה, וְכֵן הַמּוֹכֵר בְּשָׂמִים לְהִתְקַשֵּׁט בָּהֶם הַנָּשִׁים, עַל שֵׁם שֶׁמְּחַזֵּר תָּמִיד בָּעֲיָרוֹת, נִקְרָא רוֹכֵל לְשׁוֹן רוֹגֵל; לָא תֵיכוּל קוּרְצִין כְּמוֹ וַאֲכַלוּ קַרְצֵיהוֹן דִּי יְהוּדָיֵא (דניאל ב׳:כ״ה), אָכַל בֵּיהּ קוּרְצָא בֵּי מַלְכָּא (ברבות נ"ח); נִרְאֶה בְעֵינַי שֶׁהָיָה מִשְׁפָּטָם לֶאֱכֹל בְּבֵית הַמְקַבֵּל דִּבְרֵיהֶם שׁוּם הַלְעָטָה, וְהוּא גְמַר חִזּוּק שֶׁדְּבָרָיו מְקֻיָּמִים וְיַעֲמִידֵם עַל הָאֱמֶת, וְאוֹתָהּ הַלְעָטָה נִקְרֵאת אֲכִילַת קוּרְצִין, לְשׁוֹן קוֹרֵץ בְּעֵינָיו (משלי ו'), שֶׁכֵּן דֶּרֶךְ כָּל הוֹלְכֵי רָכִיל לִקְרֹץ בְּעֵינֵיהֶם וְלִרְמֹז דִּבְרֵי רְכִילוּתָן, שֶׁלֹּא יָבִינוּ שְׁאָר הַשּׁוֹמְעִים:
@16 **לא תעמד על דם רעך.** לִרְאוֹת בְּמִיתָתוֹ וְאַתָּה יָכוֹל לְהַצִּילוֹ, כְּגוֹן טוֹבֵעַ בַּנָּהָר וְחַיָּה אוֹ לִיסְטִים בָּאִים עָלָיו (סנהדרין ע"ג):
@16 **אני ה'.** נֶאֱמָן לְשַׁלֵּם שָׂכָר, וְנֶאֱמָן לִפָּרַע:
@17 **ולא תשא עליו חטא.** לֹא תַלְבִּין אֶת פָּנָיו בָּרַבִּים (עי' ספרא):
@18 **לא תקם.** אָמַר לוֹ הַשְׁאִילֵנִי מַגָּלְךָ, אָמַר לוֹ לָאו, לְמָחָר אָמַר לוֹ הַשְׁאִילֵנִי קַרְדֻּמְּךָ, אָמַר לוֹ אֵינִי מַשְׁאִילְךָ כְּדֶרֶךְ שֶׁלֹּא הִשְׁאַלְתַּנִי, זוֹ הִיא נְקִימָה; וְאֵיזוֹ הִיא נְטִירָה? אָמַר לוֹ הַשְׁאִילֵנִי אֶת קַרְדֻּמְּךָ, אָמַר לוֹ לָאו, לְמָחָר אָמַר לוֹ הַשְׁאִילֵנִי מַגָּלְךָ, אָמַר לוֹ הֵא לְךָ, אֵינִי כְמוֹתְךָ שֶׁלֹּא הִשְׁאַלְתַּנִי, זוֹ הִיא נְטִירָה, שֶׁנּוֹטֵר הָאֵיבָה בְּלִבּוֹ, אַעַ"פִּי שֶׁאֵינוֹ נוֹקֵם (ספרא; יומא כ"ג):
@18 **ואהבת לרעך כמוך.** אָמַר רַבִּי עֲקִיבָא זֶה כְּלָל גָּדוֹל בַּתּוֹרָה (ספרא):
@19 **את חקתי תשמרו.** וְאֵלּוּ הֵן: בְּהֶמְתְּךָ לֹא תַרְבִּיעַ כִּלְאַיִם וְגוֹ'; חֻקִּים — אֵלּוּ גְזֵרַת מֶלֶךְ שֶׁאֵין טַעַם לַדָּבָר:
@19 **ובגד כלאים.** לָמָּה נֶאֱמַר? לְפִי שֶׁנֶּאֱמַר "לֹא תִלְבַּשׁ שַׁעַטְנֵז צֶמֶר וּפִשְׁתִּים יַחְדָּו" (דברים כ"ב), יָכוֹל לֹא יִלְבַּשׁ גִּזֵּי צֶמֶר וַאֲנִיצֵי פִשְׁתָּן, תַּ"ל "בֶּגֶד", מִנַּיִן לְרַבּוֹת הַלְּבָדִים? תַּ"לֹ "שַׁעַטְנֵז" — דָּבָר שֶׁהוּא שׁוּעַ טָווּי וְנוּז. וְאוֹמֵר אֲנִי נוּז לְשׁוֹן דָּבָר הַנִּמְלָל וְשָׁזוּר זֶה עִם זֶה לְחַבְּרוֹ, טישט"יר בְּלַעַז, כְּמוֹ "חַזְיָין לִנְזָאֵי דְאִית בְּהוֹן" (מועד קטן י"ב), שֶׁאָנוּ מְפָרְשִׁין לְשׁוֹן כִּמּוּשׁ, פליש"טרא, וּלְשׁוֹן שַׁעַטְנֵז פֵּרֵשׁ מְנַחֵם מַחְבֶּרֶת צֶמֶר וּפִשְׁתִּים:
@20 **נחרפת לאיש.** מְיֻעֶדֶת וּמְיֻחֶדֶת לְאִישׁ, וְאֵינִי יוֹדֵעַ לוֹ דִמְיוֹן בַּמִּקְרָא; וּבְשִׁפְחָה כְנַעֲנִית חֶצְיָהּ שִׁפְחָה וְחֶצְיָהּ בַּת חֹרִין הַמְאֹרֶסֶת לְעֶבֶד עִבְרִי שֶׁמֻּתָּר בְּשִׁפְחָה הַכָּתוּב מְדַבֵּר:
@20 **והפדה לא נפדתה.** פְּדוּיָה וְאֵינָהּ פְּדוּיָה, וּסְתָם פִּדְיוֹן בְּכֶסֶף:
@20 **או חפשה.** בִּשְׁטָר (ספרא):
@20 **בקרת תהיה.** הִיא לוֹקָה וְלֹא הוּא, יֵשׁ עַל בֵּית דִּין לְבַקֵּר אֶת הַדָּבָר שֶׁלֹּא לְחַיְּבָהּ מִיתָה **כי לא חפשה** וְאֵין קִדּוּשֶׁיהָ קִדּוּשִׁין גְּמוּרִין: וְרַבּוֹתֵינוּ לָמְדוּ מִכָּאן (מכות כ"ב), שֶׁמִּי שֶׁהוּא בְמַלְקוּת תְּהֵא בִקְרִיאָה — שֶׁהַדַּיָּנִים הַמַּלְקִין קוֹרִין עַל הַלּוֹקֶה "אִם לֹא תִשְׁמֹר לַעֲשׂוֹת וְגוֹ' וְהִפְלָא ה' אֶת מַכֹּתְךָ וְגוֹ'" (דברים כ"ח):
@20 **כי לא חפשה.** לְפִיכָךְ אֵין חַיָּב עָלֶיהָ מִיתָה, שֶׁאֵין קִדּוּשֶׁיהָ קִדּוּשִׁין, הָא אִם חֻפְּשָׁה קִדּוּשֶׁיהָ קִדּוּשִׁין וְחַיָּב מִיתָה (ספרא):
@22 **ונסלח לו מחטאתו אשר חטא.** לְרַבּוֹת אֶת הַמֵּזִיד כַּשּׁוֹגֵג (ספרא):
@23 **וערלתם ערלתו.** וַאֲטַמְתֶּם אֲטִימָתוֹ — יְהֵא אָטוּם וְנִסְתָּם מִלֵּהָנוֹת מִמֶּנּוּ:
@23 **שלש שנים יהיה לכם ערלים.** מֵאֵימָתַי מוֹנֶה לוֹ? מִשְּׁעַת נְטִיעָתוֹ; יָכוֹל אִם הִצְנִיעוֹ, לְאַחַר שָׁלוֹשׁ שָׁנִים יְהֵא מֻתָּר, תַּ"ל יִהְיֶה — בַּהֲוָיָתוֹ יְהֵא (ספרא):
@24 **יהיה כל פריו קדש.** כְּמַעֲשֵׂר שֵׁנִי שֶׁכָּתוּב בּוֹ וְכָל מַעְשַׂר הָאָרֶץ וְגוֹ' קֹדֶשׁ לַה' (ויקרא כ"ז), מַה מַּעֲשֵׂר שֵׁנִי אֵינוֹ נֶאֱכָל חוּץ לְחוֹמוֹת יְרוּשָׁלַיִם אֶלָּא בְּפִדְיוֹן, אַף זֶה כֵּן, וְדָבָר זֶה **הלולים לה'** הוּא, שֶׁנּוֹשְׂאוֹ שָׁם לְשַׁבֵּחַ וּלְהַלֵּל לַשָּׁמַיִם (עי' ברכות ל"ה):
@25 **להוסיף לכם תבואתו.** הַמִּצְוָה הַזֹּאת שֶׁתִּשְׁמְרוּ, תִּהְיֶה לְהוֹסִיף לָכֶם תְּבוּאָתוֹ, שֶׁבִּשְׂכָרָהּ אֲנִי מְבָרֵךְ לָכֶם פֵּרוֹת הַנְּטִיעָה; הָיָה רַבִּי עֲקִיבָא אוֹמֵר דִּבְּרָה תוֹרָה כְּנֶגֶד יֵצֶר הָרָע, שֶׁלֹּא יֹאמַר אָדָם הֲרֵי אַרְבַּע שָׁנִים אֲנִי מִצְטַעֵר בּוֹ חִנָּם לְפִיכָךְ נֶאֱמַר לְהוֹסִיף לָכֶם תְּבוּאָתוֹ (ספרא):
@25 **אני ה'.** אֲנִי ה' הַמַּבְטִיחַ עַל כָּךְ וְנֶאֱמָן לִשְׁמֹר הַבְטָחָתִי:
@26 **לא תאכלו על הדם.** לְהַרְבֵּה פָנִים נִדְרָשׁ בְּסַנְהֶדְרִין (דף ס"ג): אַזְהָרָה שֶׁלֹּא יֹאכַל מִבְּשַֹר קָדָשִׁים לִפְנֵי זְרִיקַת דָּמִים, וְאַזְהָרָה לָאוֹכֵל מִבֶּהֱמַת חֻלִּין טֶרֶם שֶׁתֵּצֵא נַפְשָׁהּ, וְעוֹד הַרְבֵּה:
@26 **לא תנחשו.** כְּגוֹן אֵלּוּ הַמְנַחֲשִׁין בְּחֻלְדָּה וּבְעוֹפוֹת, פִּתּוֹ נָפְלָה מִפִּיו, צְבִי הִפְסִיקוֹ בַדֶּרֶךְ (ספרא):
@26 **ולא תעוננו.** לְשׁוֹן עוֹנוֹת וְשָׁעוֹת, שֶׁאוֹמֵר יוֹם פְּלוֹנִי יָפֶה לְהַתְחִיל מְלָאכָה, שָׁעָה פְלוֹנִית קָשָׁה לָצֵאת (סנהדרין ס"ה):
@27 **לא תקפו פאת ראשכם.** זֶה הַמַּשְׁוֶה צְדָעָיו לַאֲחוֹרֵי אָזְנוֹ וּלְפַדַּחְתּוֹ, וְנִמְצָא הֶקֵּף רֹאשׁוֹ עָגֹל סָבִיב, שֶׁעַל אֲחוֹרֵי אָזְנָיו עִקְּרֵי שְׂעָרוֹ לְמַעְלָה מִצְּדָעָיו הַרְבֵּה:
@27 **פאת זקנך.** סוֹף הַזָּקָן וּגְבוּלָיו (מכות כ'), וְהֵן חָמֵשׁ — שְׁתַּיִם בְּכָל לֶחִי וָלֶחִי, לְמַעְלָה אֵצֶל הָרֹאשׁ שֶׁהוּא רָחָב, וְיֵשׁ בּוֹ שְׁתֵּי פֵאוֹת, וְאַחַת לְמַטָּה בְּסַנְטֵרוֹ — מְקוֹם חִבּוּר שְׁנֵי הַלְּחָיַיִם יַחַד (שבועות נ'):
@28 **ושרט לנפש.** כֵּן דַּרְכָּן שֶׁל אֱמוֹרִיִּים לִהְיוֹת מְשָׂרְטִין בְּשָֹרָם כְּשֶׁמֵּת לָהֶם מֵת:
@28 **וכתבת קעקע.** כְּתָב מְחֻקֶּה וְשָׁקוּעַ שֶׁאֵינוֹ נִמְחָק לְעוֹלָם שֶׁמְּקַעְקְעוֹ בְּמַחַט וְהוּא מַשְׁחִיר לְעוֹלָם:
@28 **קעקע.** לְשׁוֹן וְהוֹקַע אוֹתָם (במדבר כ"ה), וְהוֹקַעְנוּם (שמואל ב כ"א), תּוֹחֲבִין עֵץ בָּאָרֶץ וְתוֹלִין אוֹתָם עֲלֵיהֶם, וְנִמְצְאוּ מְחֻקִּין וּתְחוּבִין בַּקַּרְקַע, פורפו"ינט בְּלַעַז:
@29 **אל תחלל את בתך להזנותה.** בְּמוֹסֵר בִּתּוֹ פְנוּיָה לְבִיאָה שֶׁלֹּא לְשֵׁם קִדּוּשִׁין (סנהדרין ע"ו):
@29 **ולא תזנה הארץ.** אִם אַתָּה עוֹשֶׂה כֵּן, הָאָרֶץ מְזַנָּה אֶת פֵּרוֹתֶיהָ לַעֲשׂוֹתָן בְּמָקוֹם אַחֵר וְלֹא בְאַרְצְכֶם, וְכֵן הוּא אוֹמֵר (ירמיהו ג'), וַיִּמָּנְעוּ רְבִיבִים וְגוֹ' (תוספתא, קידושין א'):
@30 **ומקדשי תיראו.** לֹא יִכָּנֵס בְּמַקְלוֹ וּבְמִנְעָלוֹ וּבַאֲפֻנְדָּתוֹ וּבְאָבָק שֶׁעַל רַגְלָיו (ברכות נ"ד); וְאַעַ"פִּי שֶׁאֲנִי מַזְהִירְכֶם עַל הַמִּקְדָּשׁ, אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ — אֵין בִּנְיַן הַמִּקְדָּשׁ דּוֹחֶה שַׁבָּת (ספרא):
@31 **אל תפנו.** אַזְהָרָה לְבַעַל אוֹב וְיִדְּעוֹנִי; בַּעַל אוֹב זֶה פִּיתוֹם הַמְדַבֵּר מִשֶּׁחְיוֹ, וְיִדְּעוֹנִי הַמַּכְנִיס עֶצֶם חַיָּה שֶׁשְּׁמָה יַדּוּעַ לְתוֹךְ פִּיו וְהָעֶצֶם מְדַבֵּר (סנהדרין ס"ה):
@31 **אל תבקשו.** לִהְיוֹת עֲסוּקִים בָּם, שֶׁאִם תַּעַסְקוּ בָם, אַתֶּם מִטַּמְּאִין לְפָנַי וַאֲנִי מְתַעֵב אֶתְכֶם:
@31 **אני ה' אלהיכם.** דְּעוּ אֶת מִי אַתֶּם מַחֲלִיפִין בְּמִי (ספרא):
@32 **מפני שיבה תקום.** יָכוֹל זָקֵן אַשְׁמַאי, תַּ"ל זָקֵן, אֵין זָקֵן אֶלָּא שֶׁקָּנָה חָכְמָה (קידושין ל"ב):
@32 **והדרת פני זקן.** אֵיזֶהוּ הִדּוּר? לֹא יֵשֵׁב בִּמְקוֹמוֹ וְלֹא יִסְתֹּר אֶת דְּבָרָיו: יָכוֹל יַעֲצִים עֵינָיו כְּמִי שֶׁלֹּא רָאָהוּ? לְכָךְ נֶאֱמַר **ויראת מאלהיך** , שֶׁהֲרֵי דָּבָר זֶה מָסוּר לְלִבּוֹ שֶׁל עוֹשֵׂהוּ, שֶׁאֵין מַכִּיר בּוֹ אֶלָּא הוּא, וְכָל דָּבָר הַמָּסוּר לַלֵּב נֶאֱמַר בוֹ וְיָרֵאתָ מֵּאֱלֹהֶיךָ (שם):
@33 **לא תונו.** אוֹנָאַת דְּבָרִים; לֹא תֹאמַר לוֹ אֶמֶשׁ הָיִיתָ עוֹבֵד עֲ"זָ וְעַכְשָׁו אַתָּה בָא לִלְמֹד תּוֹרָה שֶׁנִּתְּנָה מִפִּי הַגְּבוּרָה (בבא מציעא נ"ח):
@34 **כי גרים הייתם.** מוּם שֶׁבְּךָ אַל תֹּאמַר לַחֲבֵרְךָ (שם נ"ט):
@34 **אני ה' אלהיכם.** אֱלֹהֶיךָ וֵאלֹהָיו אֲנִי:
@35 **לא תעשו עול במשפט.** אִם לְדִין, הֲרֵי כְּבָר נֶאֱמַר לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט (פסוק ט"ו), וּמַהוּ מִשְׁפָּט הַשָּׁנוּי כָּאן? הוּא הַמִּדָּה וְהַמִּשְׁקָל וְהַמְּשׂוּרָה, מְלַמֵּד שֶׁהַמּוֹדֵד נִקְרָא דַיָּן, שֶׁאִם שִׁקֵּר בַּמִּדָּה הֲרֵי הוּא כִמְקַלְקֵל אֶת הַדִּין, וְקָרוּי עַוָּל, שָׂנאוּי וּמְשֻׁקָּץ, חֵרֶם וְתוֹעֵבָה, וְגוֹרֵם לַחֲמִשָּׁה דְבָרִים הָאֲמוּרִים בַּדַּיָּן — מְטַמֵּא אֶת הָאָרֶץ, וּמְחַלֵּל אֶת הַשֵּׁם, וּמְסַלֵּק אֶת הַשְּׁכִינָה, וּמַפִּיל אֶת יִשְׂרָאֵל בַּחֶרֶב, וּמַגְלֶה אוֹתָם מֵאַרְצָם (ספרא):
@35 **במדה.** זוֹ מִדַּת הָאָרֶץ (שם):
@35 **במשקל.** כְּמַשְׁמָעוֹ:
@35 **ובמשורה.** הִיא מִדַּת הַלַּח וְהַיָּבֵשׁ (בבא מציעא ס"א):
@36 **אבני צדק.** הֵם הַמִּשְׁקוֹלוֹת שֶׁשּׁוֹקְלִין כְּנֶגְדָּן:
@36 **איפת.** הִיא מִדַּת הַיָּבֵשׁ:
@36 **והין.** זוֹ הִיא מִדַּת הַלַּח:
@36 **אשר הוצאתי אתכם.** עַל מְנָת כֵּן; דָּ"אַ אֲנִי הִבְחַנְתִּי בְּמִצְרַיִם בֵּין טִפָּה שֶׁל בְּכוֹר לְטִפָּה שֶׁאֵינָהּ שֶׁל בְּכוֹר, וַאֲנִי הַנֶּאֱמָן לִפָּרַע מִמִּי שֶׁטּוֹמֵן מִשְׁקְלוֹתָיו בַּמֶּלַח לְהוֹנוֹת אֶת הַבְּרִיּוֹת שֶׁאֵין מַכִּירִין בָּהֶם (בבא מציעא ס"א):
@39 **ואל בני ישראל תאמר.** עוֹנְשִׁין עַל הָאַזְהָרוֹת:
@39 **מות יומת.** בְּבֵית דִּין, וְאִם אֵין כֹּחַ בְּבֵית דִּין, עַם הָאָרֶץ מְסַיְּעִין אוֹתָן (ספרא):
@39 **עם הארץ.** עַם שֶׁבְּגִינוֹ נִבְרֵאת הָאָרֶץ, עַם שֶׁעֲתִידִין לִירַשׁ הָאָרֶץ עַל יְדֵי מִצְווֹת הַלָּלוּ (שם):
@40 **אתן את פני.** פְּנַאי שֶׁלִּי — פּוֹנֶה אֲנִי מִכָּל עֲסָקַי וְעוֹסֵק בּוֹ (שם):
@40 **באיש.** וְלֹא בַצִּבּוּר (שם), שֶׁאֵין כָּל הַצִּבּוּר נִכְרָתִין:
@40 **כי מזרעו נתן למלך.** לְפִי שֶׁנֶּאֱמַר מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ (דברים י"ח), בֶּן בְּנוֹ וּבֶן בִּתּוֹ מִנַּיִן? תַּ"ל כִּי מִזַּרְעוֹ נָתַן לַמֹּלֶךְ, זֶרַע פָּסוּל מִנַּיִן? תַּ"ל בְּתִתּוֹ מִזַּרְעוֹ לַמֹּלֶךְ (ספרא; סנהדרין ס"ד):
@40 **למען טמא את מקדשי.** אֶת כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא מְקֻדֶּשֶׁת לִי, כִּלְשׁוֹן וְלֹא יְחַלֵּל אֶת מִקְדָּשַׁי (ויקרא כ"א):
@41 **ואם העלם יעלימו.** אִם הֶעְלִימוּ בְּדָבָר אֶחָד, סוֹף שֶׁיַּעְלִימוּ בִדְבָרִים הַרְבֵּה; אִם הֶעְלִימוּ סַנְהֶדְרֵי קְטַנָּה, סוֹף שֶׁיַּעְלִימוּ סַנְהֶדְרֵי גְדוֹלָה (ספרא):
@42 **ובמשפחתו.** אָמַר רַבִּי שִׁמְעון וכִי מִשְׁפָּחָה מֶה חָטְאָה? אֶלָּא לְלַמֶּדְךָ שֶׁאֵין לְךָ מִשְׁפָּחָה שֶׁיֵּשׁ בָּהּ מוֹכֵס שֶׁאֵין כֻּלָּם מוֹכְסִין — שֶׁכֻּלָּן מְחַפִּין עָלָיו (ספרא; שבועות ל"ט):
@42 **והכרתי אתו.** לָמָּה נֶאֱמַר? לְפִי שֶׁנֶּאֱמַר **ובמשפחתו** יָכוֹל יִהְיוּ כָל הַמִּשְׁפָּחָה בְּהִכָּרֵת, תַּ"ל אֹתוֹ — אוֹתוֹ בְּהִכָּרֵת וְלֹא כָל הַמִּשְׁפָּחָה בְּהִכָּרֵת אֶלָּא בְּיִסּוּרִין (שם):
@42 **לזנות אחרי המלך.** לְרַבּוֹת שְׁאַר עֲ"זָ שֶׁעֲבָדָהּ בְּכָךְ וַאֲפִלּוּ אֵין זוֹ עֲבוֹדָתָהּ (ספרא):
@44 **והתקדשתם.** זוֹ פְּרִישׁוּת עֲ"זָ (שם):
@46 **אביו ואמו קלל.** לְרַבּוֹת לְאַחַר מִיתָה (שם; סנהדרין פ"ה):
@46 **דמיו בו.** זוֹ סְקִילָה, וְכֵן כָּל מָקוֹם שֶׁנֶּאֱמַר דָּמָיו בּוֹ, דְּמֵיהֶם בָּם; וְלָמַדְנוּ מֵאוֹב וְיִדְּעוֹנִי, שֶׁנֶּאֱמַר בָּהֶם בָּאֶבֶן יִרְגְּמוּ אֹתָם דְּמֵיהֶם בָּם (ספרא; כריתות ה'). וּפְשׁוּטוֹ שֶׁל מִקְרָא, כְּמוֹ דָּמוֹ בְרֹאשׁוֹ (יהושע ב') — אֵין נֶעֱנָשׁ עַל מִיתָתוֹ אֶלָּא הוּא, שֶׁהוּא גָרַם לְעַצְמוֹ שֶׁיֵּהָרֵג:
@47 **ואיש.** פְּרָט לְקָטָן:
@47 **אשר ינאף את אשת איש.** פְּרָט לְאֵשֶׁת קָטָן, לִמְּדָנוּ שֶׁאֵין לְקָטָן קִדּוּשִׁין, וְעַל אֵיזוֹ אֵשֶׁת אִישׁ חִיַּבְתִּי לְךָ?
@47 **אשר ינאף את אשת רעהו.** פְּרָט לְאֵשֶׁת גּוֹי, לִמְּדָנוּ שֶׁאֵין קִדּוּשִׁין לְגוֹי (ספרא; סנהדרין נ"ב):
@47 **מות יומת הנאף והנאפת.** כָּל מִיתָה הָאֲמוּרָה בַתּוֹרָה סְתָם, אֵינָהּ אֶלָּא חֶנֶק (ספרא; סנהדרין נ"ה):
@49 **תבל עשו.** גְּנַאי; לָשׁוֹן אַחֵר מְבַלְבְּלִין זֶרַע הָאָב בְּזֶרַע הַבֵּן:
@50 **משכבי אשה.** מַכְנִיס כְּמִכְחוֹל בִּשְׁפוֹפֶרֶת:
@51 **ישרפו אתו ואתהן.** אֵי אַתָּה יָכוֹל לוֹמַר אִשְׁתּוֹ הָרִאשׁוֹנָה יִשְׂרְפוּ, שֶׁהֲרֵי נְשָׂאָהּ בְּהֶתֵּר וְלֹא נֶאֶסְרָה עָלָיו, אֶלָּא אִשָּׁה וְאִמָּהּ הַכְּתוּבין כָּאן שְׁתֵּיהֶן לְאִסּוּר — שֶׁנָּשָׂא חֲמוֹתוֹ וְאִמָּהּ; וְיֵשׁ מֵרַבּוֹתֵינוּ שֶׁאוֹמְרִים אֵין כָּאן אֶלָּא חֲמוֹתוֹ, וּמַהוּ אֶתְהֶן? אֶת אַחַת מֵהֶן וְלָשׁוֹן יְוָנִי הוּא הֵן אַחַת (ספרא; סנהדרין ע"ו):
@52 **ואת הבהמה תהרגו.** אִם אָדָם חָטָא בְּהֵמָה מֶה חָטְאָה? אֶלָּא מִפְּנֵי שֶׁבָּאָה לָאָדָם תַּקָּלָה עַל יָדָהּ לְפִיכָךְ אָמַר הַכָּתוּב תִּסָּקֵל, קַל וָחֹמֶר לָאָדָם, שֶׁיּוֹדֵעַ לְהַבְחִין בֵּין טוֹב לְרַע, וְגוֹרֵם רָעָה לַחֲבֵרוֹ לַעֲבֹר עֲבֵרָה; כַּיּוֹצֵא בַדָּבָר אַתָּה אוֹמֵר אַבֵּד תְּאַבְּדוּן אֶת כָּל הַמְּקֹמוֹת (דברים י"ב), הֲרֵי דְבָרִים קַל וָחֹמֶר, וּמָה אִילָנוֹת שֶׁאֵינָן רוֹאִין וְאֵינָן שׁוֹמְעִין, עַל שֶׁבָּאת תַּקָּלָה עַל יָדָם אָמְרָה תוֹרָה הַשְׁחֵת, שְׂרֹף וְכַלֵּה, הַמַּטֶּה אֶת חֲבֵרוֹ מִדֶּרֶךְ חַיִּים לְדַרְכֵי מִיתָה, עַל אַחַת כַּמָּה וְכַמָּה (ספרא):
@54 **חסד הוא.** לְשׁוֹן אֲרַמִּי חֶרְפָּה חִסּוּדָא; וּמִדְרָשׁוֹ אִם תֹּאמַר קַיִן נָשָׂא אֲחוֹתוֹ חֶסֶד עָשָׂה הַמָּקוֹם, לִבְנוֹת עוֹלָמוֹ מִמֶּנּוּ, שֶׁנֶּאֱמַר (תהילים פ"ט), עוֹלָם חֶסֶד יִבָּנֶה (ספרא; סנהדרין נ"ח):
@55 **הערה.** גִּלָּה, וְכֵן כָּל לְשׁוֹן עֶרְוָה גִּלּוּי הוּא, וְהַוָּי"ו יוֹרֶדֶת בַּתֵּיבָה לְשֵׁם דָּבָר כְּמוֹ זַעֲוָה מִגִּזְרַת וְלֹא קָם וְלֹא זָע (אסתר ה'), וְכֵן אַחֲוָה מִגִּזְרַת אָח. וְהַעֲרָאָה זוֹ נֶחְלְקוּ בָהּ רַבּוֹתֵינוּ, יֵשׁ אוֹמְרִים זוֹ נְשִׁיקַת שַׁמָּשׁ, וְיֵשׁ אוֹמְרִים זוֹ הַכְנָסַת עֲטָרָה (יבמות נ"ה):
@56 **וערות אחות אמך וגו'.** שָׁנָה הַכָּתוּב בְּאַזְהָרָתָן, לוֹמַר שֶׁהֻזְהַר עֲלֵיהֶן בֵּין עַל אֲחוֹת אָבִיו וְאִמּוֹ מִן הָאָב, בֵּין עַל אַחְיוֹתֵיהֶן מִן הָאֵם, אֲבָל עֶרְוַת אֵשֶׁת אֲחִי אָבִיו לֹא הֻזְהַר אֶלָּא עַל אֵשֶׁת אֲחִי אָבִיו מִן הָאָב (עי' יבמות נ"ד):
@57 **אשר ישכב את דדתו.** הַמִּקְרָא הַזֶּה בָּא לְלַמֵּד עַל כָּרֵת הָאָמוּר לְמַעְלָה שֶׁהוּא בְעֹנֶשׁ הֲלִיכַת עֲרִירִי:
@57 **ערירים.** כְּתַרְגּוּמוֹ, בְּלָא וְלָד, וְדוֹמֶה לוֹ וְאָנֹכִי הוֹלֵךְ עֲרִירִי (בראשית ט"ו); יֵשׁ לוֹ בָנִים, קוֹבְרָן, אֵין לוֹ בָנִים, מֵת בְּלֹא בָנִים, לְכָךְ שִׁנָּה בִשְׁנֵי מִקְרָאוֹת אֵלּוּ — עֲרִירִים "יָמֻתוּ", עֲרִירִים "יִהְיוּ", **ערירים ימתו.** אִם יִהְיוּ לוֹ בִשְׁעַת עֲבֵרָה לֹא יִהְיוּ לוֹ כְּשֶׁיָּמוּת, לְפִי שֶׁקּוֹבְרָן בְּחַיָּיו, **ערירים יהיו.** אִם אֵין לוֹ בִּשְׁעַת עֲבֵרָה, יִהְיֶה כָל יָמָיו כְּמוֹ שֶׁהוּא עַכְשָׁו (ספרא; יבמות נ"ה):
@58 **נדה הוא.** הַשְּׁכִיבָה הַזֹּאת מְנֻדָּה הִיא וּמְאוּסָה; וְרַבּוֹתֵינוּ דָּרְשׁוּ לֶאֱסֹר הַעֲרָאָה בָהּ כְּנִדָּה שֶׁהַעֲרָאָה מְפֹרֶשֶׁת בָּהּ — אֶת מְקֹרָהּ הֶעֱרָה (יבמות נ"ד):
@60 **ואקץ.** לְשׁוֹן מִאוּס, כְּמוֹ קַצְתִּי בְחַיַּי (בראשית כ"ז), כְּאָדָם שֶׁהוּא קָץ בִּמְזוֹנוֹ (ספרא):
@62 **והבדלתם בין הבהמה הטהרה לטמאה.** אֵין צָרִיךְ לוֹמַר בֵּין פָּרָה לַחֲמוֹר, שֶׁהֲרֵי מֻבְדָּלִין וְנִכָּרִין הֵם, אֶלָּא בֵּין טְהוֹרָה לְךָ לִטְמֵאָה לְךָ — בֵּין שֶׁנִּשְׁחַט רֻבּוֹ שֶׁל סִימָן לְנִשְׁחַט חֶצְיוֹ, וְכַמָּה בֵּין רֻבּוֹ לְחֶצְיוֹ? מְלֹא שְׂעָרָה (ספרא):
@62 **אשר הבדלתי לכם לטמא.** לֶאֱסֹר:
@63 **ואבדל אתכם מן העמים להיות לי.** אִם אַתֶּם מֻבְדָּלִים מֵהֶם הֲרֵי אַתֶּם שֶׁלִּי, וְאִם לָאו הֲרֵי אַתֶּם שֶׁל נְבוּכַדְנֶאצַּר וַחֲבֵרָיו; רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה אוֹמֵר מִנַּיִן שֶׁלֹּא יֹאמַר אָדָם נַפְשִׁי קָצָה בִּבְשַׂר חֲזִיר, אִי אֶפְשִׁי לִלְבֹּשׁ כִּלְאַיִם, אֲבָל יֹאמַר אֶפְשִׁי וּמָה אֶעֱשֶׂה וְאָבִי שֶׁבַּשָּׁמַיִם גָּזַר עָלַי? תַּ"ל וָאַבְדִּל אֶתְכֶם מִן הָעַמִּים לִהְיוֹת לִי, שֶׁתְּהֵא הַבְדָּלַתְכֶם מֵהֶם לִשְׁמִי — פּוֹרֵשׁ מִן הָעֲבֵרָה וּמְקַבֵּל עָלָיו עֹל מַלְכוּת שָׁמָיִם (ספרא):
@64 **כי יהיה בהם אוב וגו'.** כָּאן נֶאֱמַר בָּהֶם מִיתָה וּלְמַעְלָה כָרֵת, עֵדִים וְהַתְרָאָה בִּסְקִילָה, מֵזִיד בְּלֹא הַתְרָאָה בְּהִכָּרֵת, וְשִׁגְגָתָם חַטָּאת, וְכֵן בְּכָל חַיָּבֵי מִיתוֹת שֶׁנֶּאֱמַר בָּהֶם כָּרֵת:

@2 **אֶל כָּל עֲדַת בְּנֵי יִשְׂרָאֵל** כְּבָר אָמְרוּ רַבּוֹתֵינוּ (תו"כ ריש הפרשה) שֶׁהַפָּרָשָׁה הַזּוֹ נֶאֶמְרָה בְּהַקְהֵל מִפְּנֵי שֶׁרֹב גּוּפֵי תוֹרָה תְּלוּיִין בָּהּ, וְזֶה טַעַם "אֶל כָּל עֲדַת בְּנֵי יִשְׂרָאֵל". אֲבָל הֻזְכְּרָה כָּאן בְּתוֹרַת הַכֹּהֲנִים מִפְּנֵי שֶׁיְּדַבֵּר בָּהּ עַל קָרְבַּן הַשְּׁלָמִים, וּמִפְּנֵי שֶׁיַּזְכִּיר בָּהּ הַמִּשְׁפָּט שֶׁיְּצַוֶּה לַעֲשׂוֹת בְּעוֹשֵׂי הַתּוֹעֵבוֹת הַנִּזְכָּרוֹת. וְהָעֲרָיוֹת וְהַתּוֹעֵבוֹת הֻזְכְּרוּ בַּסֵּפֶר הַזֶּה מִפְּנֵי הַטַּעַם שֶׁכָּתַבְנוּ בִּתְחִלַּת הַסֵּפֶר:
@2 **קְדוֹשִׁים תִּהְיוּ** הֱווּ פְּרוּשִׁים מִן הָעֲרָיוֹת וּמִן הָעֲבֵרָה, שֶׁכָּל מָקוֹם שֶׁאַתָּה מוֹצֵא גֶּדֶר עֶרְוָה אַתָּה מוֹצֵא קְדֻשָּׁה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:ב'). אֲבָל בְּתוֹרַת כֹּהֲנִים (פרשה א ב) רָאִיתִי סְתָם, פְּרוּשִׁים תִּהְיוּ. וְכֵן שָׁנוּ שָׁם (שמיני פרק יב ג), "וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדֹשִׁים כִּי קָדוֹשׁ אָנִי", כְּשֵׁם שֶׁאֲנִי קָדוֹשׁ כָּךְ אַתֶּם תִּהְיוּ קְדוֹשִׁים, כְּשֵׁם שֶׁאֲנִי פָּרוּשׁ כָּךְ אַתֶּם תִּהְיוּ פְּרוּשִׁים. וּלְפִי דַּעְתִּי אֵין הַפְּרִישׁוּת הַזּוֹ לִפְרֹשׁ מִן הָעֲרָיוֹת כְּדִבְרֵי הָרַב, אֲבָל הַפְּרִישׁוּת הִיא הַמֻּזְכֶּרֶת בְּכָל מָקוֹם בַּתַּלְמוּד שֶׁבְּעָלֶיהָ נִקְרָאִים "פְּרוּשִׁים". וְהָעִנְיָן כִּי הַתּוֹרָה הִזְהִירָה בָּעֲרָיוֹת וּבַמַּאֲכָלִים הָאֲסוּרִים, וְהִתִּירָה הַבִּיאָה אִישׁ בְּאִשְׁתּוֹ וַאֲכִילַת הַבָּשָׂר וְהַיַּיִן. א"כ יִמְצָא בַּעַל הַתַּאֲוָה מָקוֹם לִהְיוֹת שָׁטוּף בְּזִמַּת אִשְׁתּוֹ אוֹ נָשָׁיו הָרַבּוֹת, וְלִהְיוֹת בְּסֹבְאֵי יָיִן בְּזֹלֲלֵי בָשָׂר לָמוֹ, וִידַבֵּר כִּרְצוֹנוֹ בְּכָל הַנְּבָלוֹת, שֶׁלֹּא הֻזְכַּר אִסּוּר זֶה בַּתּוֹרָה, וְהִנֵּה יִהְיֶה נָבָל בִּרְשׁוּת הַתּוֹרָה. לְפִיכָךְ בָּא הַכָּתוּב אַחֲרֵי שֶׁפֵּרֵט הָאִסּוּרִים שֶׁאָסַר אוֹתָם לְגַמְרֵי, וְצִוָּה בְּדָבָר כְּלָלִי - שֶׁנִּהְיֶה פְּרוּשִׁים מִן הַמֻּתָּרוֹת: יְמַעֵט בַּמִּשְׁגָּל, כְּעִנְיָן שֶׁאָמְרוּ (ברכות כב) שֶׁלֹּא יִהְיוּ תַּלְמִידֵי חֲכָמִים מְצוּיִין אֵצֶל נְשׁוֹתֵיהֶן כַּתַּרְנְגֹלִין, וְלֹא יְשַׁמֵּשׁ אֶלָּא כְּפִי הַצָּרִיךְ בְּקִיּוּם הַמִּצְוָה מִמֶּנּוּ; וִיקַדֵּשׁ עַצְמוֹ מִן הַיַּיִן בְּמִעוּטוֹ, כְּמוֹ שֶׁקָּרָא הַכָּתוּב (במדבר ו ה) הַנָּזִיר - "קָדוֹשׁ", וְיִזְכֹּר הָרָעוֹת הַנִּזְכָּרוֹת מִמֶּנּוּ בַּתּוֹרָה (בראשית ט כא) בְּנֹחַ וּבְלוֹט; וְכֵן יַפְרִישׁ עַצְמוֹ מִן הַטֻּמְאָה, אע"פ שֶׁלֹּא הֻזְהַרְנוּ מִמֶּנָּה בַּתּוֹרָה, כְּמוֹ שֶׁהִזְכִּירוּ (חגיגה יח), בִּגְדֵי עַם הָאָרֶץ מִדְרָס לַפְּרוּשִׁים, וּכְמוֹ שֶׁנִּקְרָא הַנָּזִיר "קָדוֹשׁ" (במדבר ו ח) בְּשָׁמְרוֹ מִטֻּמְאַת הַמֵּת גַּם כֵּן; וְגַם יִשְׁמֹר פִּיו וּלְשׁוֹנוֹ מֵהִתְגָּאֵל בְּרִבּוּי הָאֲכִילָה הַגַּסָּה וּמִן הַדִּבּוּר הַנִּמְאָס, כְּעִנְיָן שֶׁהִזְכִּיר הַכָּתוּב (ישעיהו ט טז) "וְכָל פֶּה דֹּבֵר נְבָלָה", וִיקַדֵּשׁ עַצְמוֹ בָּזֶה עַד שֶׁיַּגִּיעַ לַפְּרִישׁוּת, כְּמָה שֶׁאָמְרוּ עַל רַבִּי חִיָּא שֶׁלֹּא שָׂח שִׂיחָה בְּטֵלָה מִיָּמָיו. בְּאֵלּוּ וּבְכַיּוֹצֵא בָּהֶן בָּאָה הַמִּצְוָה הַזֹּאת הַכְּלָלִית, אַחֲרֵי שֶׁפֵּרֵט כָּל הָעֲבֵרוֹת שֶׁהֵן אֲסוּרוֹת לְגַמְרֵי, עַד שֶׁיִּכָּנֵס בִּכְלַל זֹאת הַצַּוָּאָה הַנְּקִיּוּת בְּיָדָיו וְגוּפוֹ, כְּמוֹ שֶׁאָמְרוּ (ברכות נג) "וְהִתְקַדִּשְׁתֶּם" אֵלּוּ מַיִם רִאשׁוֹנִים, "וִהְיִיתֶם קְדֹשִׁים" אֵלּוּ מַיִם אַחֲרוֹנִים, "כִּי קָדוֹשׁ" זֶה שֶׁמֶן עָרֵב. כִּי אע"פ שֶׁאֵלּוּ מִצְוֹת מִדִּבְרֵיהֶם, עִקַּר הַכָּתוּב בְּכַיּוֹצֵא בָּזֶה יַזְהִיר שֶׁנִּהְיֶה נְקִיִּים וּטְהוֹרִים וּפְרוּשִׁים מֵהֲמוֹן בְּנֵי אָדָם, שֶׁהֵם מְלַכְלְכִים עַצְמָם בַּמֻּתָּרוֹת וּבַכִּעוּרִים. וְזֶה דֶּרֶךְ הַתּוֹרָה לִפְרֹט וְלִכְלֹל בְּכַיּוֹצֵא בָּזֶה, כִּי אַחֲרֵי אַזְהָרַת פְּרָטֵי הַדִּינִין בְּכָל מַשָּׂא וּמַתָּן שֶׁבֵּין בְּנֵי אָדָם, לֹא תִּגְנֹב וְלֹא תִּגְזֹל וְלֹא תּוֹנוּ וּשְׁאָר הָאַזְהָרוֹת, אָמַר בִּכְלָל "וְעָשִׂיתָ הַיָּשָׁר וְהַטּוֹב" (דברים ו יח), שֶׁיַּכְנִיס בַּעֲשֵׂה הַיֹּשֶׁר וְהַהַשְׁוָיָה וְכָל לִפְנִים מִשּׁוּרַת הַדִּין לִרְצוֹן חֲבֵרָיו, כַּאֲשֶׁר אֲפָרֵשׁ (שם) בְּהַגִּיעִי לִמְקוֹמוֹ בִּרְצוֹן הקב"ה. וְכֵן בְּעִנְיַן הַשַּׁבָּת, אָסַר הַמְּלָאכוֹת בְּלָאו וְהַטְּרָחִים בַּעֲשֵׂה כְּלָלִי, שֶׁנֶּאֱמַר "תִּשְׁבֹּת", וְעוֹד אֲפָרֵשׁ זֶה (רמב"ן על ויקרא כ"ג:כ"ד) בע"ה:
@2 וְטַעַם הַכָּתוּב שֶׁאָמַר **כִּי קָדוֹשׁ אֲנִי ה' אֱלֹהֵיכֶם** , לוֹמַר שֶׁאֲנַחְנוּ נִזְכֶּה לְדָבְקָה בּוֹ בִּהְיוֹתֵנוּ קְדוֹשִׁים, וְהִנֵּה זֶה כְּעִנְיַן הַדִּבּוּר הָרִאשׁוֹן בַּעֲשֶׂרֶת הַדִּבְּרוֹת (שמות כ ב) (ג). וְצִוָּה "אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ" (ויקרא י"ט:ג'), כִּי שָׁם צִוָּה עַל הַכָּבוֹד וְכָאן יְצַוֶּה עַל הַמּוֹרָא. וְאָמַר "וְאֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ", כִּי שָׁם צִוָּה עַל הַזְּכִירָה וְכָאן עַל הַשְּׁמִירָה. וּכְבָר פֵּרַשְׁנוּ (שמות כ ח) עִנְיַן שְׁנֵיהֶם:
@4 וְאָמַר **אַל תִּפְנוּ אֶל הָאֱלִילִם** וְהוּא מִלְּשׁוֹן "וְאִם יִפְנֶה לְבָבְךָ" (דברים ל יז), "אֲשֶׁר לְבָבוֹ פֹנֶה הַיּוֹם" (שם כט יז), יֹאמַר שֶׁלֹּא יִפְנֶה לִבּוֹ בָּאֱלִילִים לְהַאֲמִין שֶׁיִּהְיֶה בָּהֶם תּוֹעֶלֶת אוֹ שֶׁיָּבֹאוּ הָעֲתִידוֹת אֲשֶׁר יִתְנַבְּאוּ מֵהֶם, אֲבָל יִהְיוּ הֵם וְכָל מַעֲשֵׂיהֶם אֶפֶס וָתֹהוּ בְּעֵינָיו, וְלֹא תָּבֹא הָעֲתִידָה רַק בִּגְזֵרַת עֶלְיוֹן. וְכָךְ אָמְרוּ רַבּוֹתֵינוּ (שבת קמט), דְּיוֹקָנוֹת עַצְמָן אָסוּר לְהִסְתַּכֵּל בָּהֶן מִשּׁוּם שֶׁנֶּאֱמַר "אַל תִּפְנוּ אֶל הָאֱלִילִים". הִכְנִיסוּ אֲפִלּוּ הַהִסְתַּכְּלוּת בָּהֶן בִּכְלַל הָאִסּוּר, שֶׁלֹּא יִתֵּן דַּעְתּוֹ בְּעִנְיָנָם כְּלָל. וְאָמַר **וֵאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם** לְהַזְהִיר עֲלֵיהֶם מִשְּׁעַת עֲשִׂיָּה. וְהָאַזְהָרוֹת בַּעֲבוֹדָה זָרָה יָבֹאוּ בַּתּוֹרָה בִּמְקוֹמוֹת רַבִּים. וּבְמִדְרַשׁ וַיִּקְרָא רַבָּה (כד ה) הִזְכִּירוּ עַל הַפָּרָשָׁה הַזּוֹ, רַבִּי לֵוִי אוֹמֵר, מִפְּנֵי שֶׁעֲשֶׂרֶת הַדִּבְּרוֹת כְּלוּלִין בְּתוֹכָהּ: "אָנֹכִי ה' אֱלֹהֶיךָ" (שמות כ ב), וּכְתִיב הָכָא "אֲנִי ה' אֱלֹהֵיכֶם"; "לֹא יִהְיֶה לְךָ" (שם כ ג), וּכְתִיב הָכָא "וֵאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם"; "לֹא תִשָּׂא" (שם כ ז), וּכְתִיב הָכָא (ויקרא י"ט:י"ב) "וְלֹא תִשָּׁבְעוּ בִשְׁמִי לַשָּׁקֶר"; "זָכוֹר אֶת יוֹם הַשַּׁבָּת" (שם כ ח), וּכְתִיב הָכָא "וְאֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ"; "כַּבֵּד אֶת אָבִיךָ וְאֶת אִמֶּךָ" (שם כ יב), וּכְתִיב הָכָא "אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ"; "לֹא תִּרְצָח" (שם כ יג), וּכְתִיב הָכָא (ויקרא י"ט:ט"ז) "לֹא תַעֲמֹד עַל דַּם רֵעֶךָ"; "לֹא תִּנְאָף" (שם כ יג), וּכְתִיב הָכָא (ויקרא י"ט:כ"ט) "אַל תְּחַלֵּל אֶת בִּתְּךָ לְהַזְנוֹתָהּ"; "לֹא תִּגְנֹב" (שם כ יג), וּכְתִיב הָכָא (ויקרא י"ט:י"א) "לֹא תִּגְנֹבוּ"; "לֹא תַעֲנֶה" (שם כ יג), וּכְתִיב הָכָא (ויקרא י"ט:ט"ז) "לֹא תֵלֵךְ רָכִיל בְּעַמֶּךָ"; "לֹא תַחְמֹד" (שם כ יד), וּכְתִיב הָכָא "וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ" (ויקרא י"ט:י"ח), ע"כ בַּמִּדְרָשׁ:
@5 וְאָמַר **וְכִי תִזְבְּחוּ זֶבַח שְׁלָמִים** כִּי אַחֲרֵי שֶׁאָסַר הַזְּבִיחָה וְכָל עֲבוֹדָה לָאֱלִילִים וְלֵאלֹהֵי מַסֵּכָה, וְרִקֵּן כָּל הָעֲבוֹדוֹת כֻּלָּן לַשֵּׁם הַמְיֻחָד, אָמַר כִּי כַּאֲשֶׁר תִּזְבְּחוּ לַשֵּׁם לֹא תִּזְבְּחוּ לוֹ אֶלָּא לִרְצוֹנְכֶם, שֶׁתִּהְיֶה עֲבֹדַתְכֶם לְרָצוֹן לְפָנָיו, וְיִרְצֶה בָּכֶם כְּעֶבֶד יִתְרַצֶּה אֶל אֲדֹנָיו בַּעֲשׂוֹתוֹ כָּל אֲשֶׁר יְצַוֶּנּוּ, כִּלְשׁוֹן "וְנִרְצָה לוֹ לְכַפֵּר עָלָיו" (ויקרא א':ד'), "וְאוֹר פָּנֶיךָ כִּי רְצִיתָם" (תהלים מד ד). וְהַטַּעַם שֶׁלֹּא תַּחְשְׁבוּ שֶׁיִּהְיֶה בַּעֲבוֹדָה זָרָה שׁוּם תּוֹעֶלֶת, וְלֹא תַּעֲשׂוּ עֲבוֹדַת ה' הַנִּכְבָּד עַל מְנָת לְקַבֵּל פְּרָס אֶלָּא לַעֲשׂוֹת רְצוֹנוֹ, כִּי רְצוֹנוֹ הַפָּשׁוּט הוּא הָרָאוּי וְהַמְּחַיֵּב. וְאוֹמֵר זֶה בַּשְּׁלָמִים, שֶׁהֵם הַקֳּדָשִׁים קַלִּים הַנֶּאֱכָלִים לַבְּעָלִים בְּעַצְמָם, שֶׁיִּשְׁמְרוּ בְּמַחְשַׁבְתָּם לִהְיוֹתָם בְּכַוָּנָה רְצוּיָה, וְכָל שֶׁכֵּן בְּקָדְשֵׁי הַקֳּדָשִׁים. אוֹ מִפְּנֵי שֶׁהַשְּׁלָמִים מִדָּתָן שֶׁל יִשְׂרָאֵל, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ (זבחים קטז), לֹא הִקְרִיבוּ בְּנֵי נֹחַ שְׁלָמִים, וְהַמַּשְׂכִּיל יָבִין. וְרַבּוֹתֵינוּ אָמְרוּ (חולין יג), לִרְצוֹנְכֶם זְבוֹחוּ, שֶׁתִּזְבְּחוּ לְדַעְתְּכֶם, שֶׁהַמִּתְעַסֵּק בְּקָדָשִׁים פָּסוּל:
@12 **וְלֹא תִשָּׁבְעוּ בִשְׁמִי לַשָּׁקֶר** לָמָּה נֶאֱמַר, לְפִי שֶׁנֶּאֱמַר (שמות כ ז) "לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךָ לַשָּׁוְא", יָכוֹל לֹא יְהֵא חַיָּב אֶלָּא עַל הַשֵּׁם הַמְיֻחָד, מִנַּיִן לְרַבּוֹת כָּל הַכִּנּוּיִין, תַּלְמוּד לוֹמַר "לֹא תִשָּׁבְעוּ בִשְׁמִי לַשָּׁקֶר", כָּל שֵׁם שֶׁיֵּשׁ לִי, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:י"ב) מִתּוֹרַת כֹּהֲנִים (פרשה ב ו). וְעַל דֶּרֶךְ הָאֱמֶת, "לֹא תִשָּׁבְעוּ בִשְׁמִי" הוּא הַשֵּׁם הַמְּיֻחָד, "וְחִלַּלְתָּ אֶת שֵׁם אֱלֹהֶיךָ", הוּא הָאֱלֹהִים שֶׁמִּמֶּנּוּ נִתְרַבּוּ כָּל הַכִּנּוּיִין, וְשָׁם נֶאֱמַר תְּחִלָּה "שֵׁם ה' אֱלֹהֶיךָ" וְ"כִי לֹא יְנַקֶּה ה'" בִּשְׁמוֹ הַגָּדוֹל הַמְּיֻחָד. וְזֶה טַעַם "וְחִלַּלְתָּ", כִּי כַּאֲשֶׁר יִשָּׁבַע בַּשֵּׁם הַמְּיֻחָד לַשֶּׁקֶר יִהְיֶה מְחַלֵּל שֵׁם אֱלֹהָיו:
@14 **לֹא תְקַלֵּל חֵרֵשׁ** אֵין לִי אֶלָּא חֵרֵשׁ, מִנַּיִן לְרַבּוֹת כָּל אָדָם, תַּלְמוּד לוֹמַר "בְעַמְּךָ לֹא תָאֹר" (שמות כב כז). א"כ לָמָּה נֶאֱמַר חֵרֵשׁ, מַה חֵרֵשׁ מְיֻחָד שֶׁהוּא בַּחַיִּים, יָצָא הַמֵּת שֶׁאֵינוֹ בַּחַיִּים, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:י"ד). וְהוּא שָׁנוּי בְּתוֹרַת כֹּהֲנִים (פרשה ב יג). אֲבָל הַמִּדְרָשׁ בַּגְּמָרָא (סנהדרין סו) אֵינוֹ כֵן, אֶלָּא הִזְהִיר הַכָּתוּב בַּנִּכְבָּדִים בָּעָם, הַדַּיָּן וְהַנָּשִׂיא, שֶׁאָמַר (שמות כב כז) "אֱלֹהִים לֹא תְקַלֵּל וְנָשִׂיא בְעַמְּךָ לֹא תָאֹר", וְחָזַר וְהִזְהִיר (כאן) בָּאֲמֵלָלִים שֶׁבָּעָם, וְהוּא הַחֵרֵשׁ, וּמֵהֶם יִלְמְדוּ בִּנְיַן אָב אֶל כָּל שְׁאָר הָעָם, כִּי מִן הָרֹאשׁ וְעַד הַסּוֹף הַכֹּל בִּכְלַל הָאַזְהָרָה. וּמִלַּת "בְעַמְּךָ" נִדְרָשׁ (בסנהדרין פה) - בְּעוֹשֵׂה מַעֲשֵׂה עַמְּךָ, לְהוֹצִיא הָרְשָׁעִים. וְעַל דֶּרֶךְ הַפְּשָׁט, הִזְכִּיר הַחֵרֵשׁ בַּקְּלָלָה כִּי אע"פ שֶׁלֹּא יִשְׁמַע וְלֹא יִתְקַצֵּף בְּקִלְלָתוֹ, הִזְהִירָה הַתּוֹרָה עָלָיו, וְאֵין צָרִיךְ לוֹמַר בַּשּׁוֹמְעִים שֶׁיִּתְבַּיְּשׁוּ וְיִחַר לָהֶם מְאֹד. וְעוֹד כִּי יַזְהִיר בַּהוֹוֶה, שֶׁאָדָם מְקַלֵּל הַחֵרֵשׁ וּמַכְשִׁיל הָעִוֵּר, שֶׁלֹּא יִירָא מֵהֶם כִּי לֹא יֵדְעוּ וְלֹא יָבִינוּ, עַל כֵּן "וְיָרֵאתָ מֵּאֱלֹהֶיךָ" (כאן), שֶׁהוּא רוֹאֶה הַנִּסְתָּרוֹת. וְהוֹסִיף לָאו אַחֵר בַּמּוֹשְׁלִים, הַנָּשִׂיא וְהַדַּיָּן, בַּעֲבוּר שֶׁדֶּרֶךְ הָאֲנָשִׁים לְקַלְּלָם בְּחַדְרֵי מִשְׁכָּבָם כַּאֲשֶׁר בְּהִשָּׁפְטוֹ יֵצֵא רָשָׁע, וּבְקִלְלַת הַנָּשִׂיא וְהַדַּיָּן תַּקָּלוֹת רַבּוֹת, כִּי הֲמוֹן הָעָם בְּסִכְלוּתָם יִשְׂנְאוּ אוֹתָם וְיִתְעוֹרְרוּ לָקוּם עֲלֵיהֶם, וְהֵם בְּמִשְׁפָּטָם יַעֲמִידוּ אָרֶץ:
@16 **לֹא תֵלֵךְ רָכִיל בְּעַמֶּךָ** אוֹמֵר אֲנִי, עַל שֵׁם שֶׁכָּל מְשַׁלְּחֵי מְדָנִים וּמְסַפְּרֵי לָשׁוֹן הָרַע הוֹלְכִים בְּבֵית רֵעֵיהֶם לְרַגֵּל מַה יִרְאוּ רָע אוֹ מַה יִשְׁמְעוּ רָע לְסַפֵּר בַּשּׁוּק, נִקְרָאִים "הוֹלְכֵי רָכִיל", "הוֹלְכֵי רְגִילָה" וְכוּ'. וְכֵן תִּרְגֵּם אוּנְקְלוֹס (תרגום אונקלוס על ויקרא י"ט:ט"ז): "לָא תֵיכוֹל קֻרְצִין", (דניאל ג ח): "וַאֲכַלוּ קַרְצֵיהוֹן דִּי יְהוּדָיֵא", (בבא מציעא פו א): "אֲכַלוּ קוּרְצָא בֵּי מַלְכָּא". נִרְאֶה בְּעֵינַי שֶׁהָיָה מִשְׁפָּטָם לֶאֱכֹל בְּבֵית הַמְקַבֵּל דִּבְרֵיהֶם שׁוּם הַלְעָטָה, וְהוּא גְּמַר חִזּוּק, שֶׁדְּבָרָיו מְקֻיָּמִים וְיַעֲמִידֵם עַל הָאֱמֶת. וְאוֹתָהּ הַלְעָטָה נִקְרֵאת אֲכִילַת קוּרְצִין, לְשׁוֹן (משלי ו יג): "קוֹרֵץ בְּעֵינָיו", שֶׁכֵּן דֶּרֶךְ הוֹלֵךְ רָכִיל לִקְרֹץ בְּעֵינָיו וְלִרְמֹז דִּבְרֵי רְכִילוּת שֶׁלֹּא יָבִינוּ הַשּׁוֹמְעִים; כָּל זֶה לְשׁוֹן הָרַב. וְאֵין בְּמָה שֶׁפֵּרֵשׁ בַּתַּרְגּוּם הַזֶּה טַעַם אוֹ רֵיחַ, כִּי הַשּׁוֹמֵעַ מִן הָרָכִיל לֹא יִשָּׁבַע לוֹ שֶׁיַּאֲמִין דְּבָרָיו וְלֹא יִתֵּן לוֹ אוֹת וּמוֹפֵת, גַּם הַמַּלְשִׁין עֶבֶד אֶל אֲדוֹנָיו לֹא יַבְטִיחֶנּוּ הָאָדוֹן שֶׁיִּשְׁמַע אֵלָיו, וּמַה טַעַם לָאֲכִילָה הַזֹּאת? וּנְבוּכַדְנֶאצַּר, בְּהוֹדָאַת הַצַּדִּיקִים עָשָׂה מַה שֶׁעָשָׂה, לֹא הֶאֱכִילָם לַמַּלְשִׁינִים וְלֹא נִשְׁבַּע לָהֶם וְגַם לֹא הֶאֱמִין לָהֶם, אֲבָל שָׁאַל (דניאל ג יד): "הַצְדָּא שַׁדְרַךְ מֵישַׁךְ וְגוֹ'", וְצִוָּה שֶׁיִּשְׁתַּחֲווּ מִכָּאן וְאֵילָךְ, וְהָיָה מַעֲבִיר עַל מַה שֶׁעָבְרוּ. וְדָרְיָוֶשׁ לֹא הֶאֱכִיל לְמַלְשִׁינֵי דָּנִיֵּאל רַק לַעֲנָה וָרֹאשׁ, וְכָתוּב בָּהֶן (דניאל ו':כ"ה): "דִּי אֲכַלוּ קַרְצוֹהִי דִּי דָנִיֵּאל". וַאֲפִלּוּ אִם אֱמֶת הַדָּבָר שֶׁיֵּעָשֶׂה כֵן בַּזְּמַנִּים הָהֵם, אַחַר שֶׁהַכָּתוּב אָמַר "לֹא תֵלֵךְ רָכִיל בְּעַמֶּךָ", לָמָּה יַזְכִּיר אוּנְקְלוֹס מִנְהַג הַשְּׁטוּת הַהוּא וְאֵין לָאַזְהָרָה עִנְיָן בּוֹ? אֲבָל עִקַּר לְשׁוֹן הָאֲרַמִּית בְּכָאן אֵינֶנּוּ אֶלָּא לְשׁוֹן הַשְׁמָעַת קוֹל, וְהוּא מֻרְגָּל בְּדִבְרֵי חֲכָמִים (בבא בתרא ה א): "וְעִזָּא לָאו אַכְלוֹיֵי מְכַלּוּ לֵיהּ וְלָאו גַּבְרָא בָּעֵי לְאַכְלוֹיֵי", וְתִרְגֵּם יוֹנָתָן: (ישעיהו נח א) "קְרָא בְגָרוֹן" - "אַכְלֵי", (ישעיהו ה כו) "וְשָׁרַק לוֹ מִקְצֵה הָאָרֶץ" - "וְיַכְלֵי לֵיהּ", (ישעיהו ה ל) "וְיִנְהֹם עָלָיו כְּנַהֲמַת יָם" - "וְיַכְלֵי עֲלֵיהוֹן", וְכֵן בִּמְקוֹמוֹת רַבִּים. וְהִנֵּה הוּא לְשׁוֹן כָּל מַשְׁמִיעַ קוֹל שֶׁיּוֹדִיעַ חֶפְצוֹ בְּלֹא חִתּוּךְ מִלּוֹת, וְלָכֵן יֹאמַר כֵּן (בגמ' שם) בַּצּוֹעֵק לְעִזִּים הַנִּכְנָסוֹת בַּשָּׂדֶה, וִיתַרְגֵּם כֵּן הַשּׂוֹרֵק וְהַנּוֹהֵם וְהַצּוֹעֵק. וְדֶרֶךְ הָרְכִילִים לָבֹא בָּרַבִּים אוֹ לִפְנֵי הַמּוֹשֵׁל, וְיִנְהֲמוּ בִּגְרוֹנָם וְיִקְרְצוּ בְּעֵינֵיהֶם לִרְמֹז כִּי שָׁמְעוּ דְּבָרִים, עַד שֶׁיִּפְצְרוּ בָּהֶם וְיַגִּידוּ אוֹתָן, עַל כֵּן נִקְרָאִים "אוֹכְלֵי קֻרְצִין", נוֹהֲמִים בִּרְמָזִים. וְאוּנְקְלוֹס תִּרְגֵּם רְכִילוּת - עִנְיָנוֹ, וְכֵן שְׁמוֹ בִּלְשׁוֹן הָאֲרַמִּית, וְלֹא חָשַׁשׁ לְפָרֵשׁ לְשׁוֹן הַכָּתוּב, וְכֵן דַּרְכּוֹ תָּמִיד, כִּי לְהָבִין הָעִנְיָן הוּא מִתְכַּוֵּן. אֲבָל בִּלְשׁוֹן הַקֹּדֶשׁ הָיוּ קוֹרִין אוֹתָם "הוֹלְכֵי רָכִיל", מִן (שיר השירים ג ו): "אַבְקַת רוֹכֵל", (יחזקאל כו יב): "רְכֻלָּתֵךְ", כִּי הָרוֹכֵל הוֹלֵךְ כָּל הַיּוֹם קוֹנֶה מִכָּאן וּמִכָּאן וְהוֹלֵךְ וּמוֹכֵר בִּמְקוֹמוֹת אֲחֵרִים בְּכָאן וּבְכָאן, כְּמוֹ שֶׁמַּזְכִּירִין חֲכָמִים (משנה מעשרות ב ג): "רוֹכְלִין הַמְּחַזְּרִים בָּעֲיָרוֹת". וְזֶה טַעַם "בְּעַמֶּךָ", כִּי הוּא הוֹלֵךְ בָּרַבִּים. וּלְהַבְדִּיל בֵּין שְׁנֵיהֶם הָיָה שֵׁם זֶה "רוֹכֵל" פֹּעַל וְשֵׁם זֶה "רָכִיל" שֵׁם תֹּאַר בְּעַצְמוֹ, כְּמוֹ "סָרִיס", "נָזִיר", יִרְמֹז הַשֵּׁם כִּי בְּנַפְשׁוֹ הוּא וְעָלָיו תָּשׁוּב:
@17 **לֹא תִשְׂנָא אֶת אָחִיךָ בִּלְבָבֶךָ** בַּעֲבוּר שֶׁדֶּרֶךְ הַשּׂוֹנְאִים לְכַסּוֹת אֶת שִׂנְאָתָם בְּלִבָּם, כְּמוֹ שֶׁאָמַר (משלי כו כד) "בִּשְׂפָתָיו יִנָּכֵר שׂוֹנֵא", הִזְכִּיר הַכָּתוּב בַּהוֹוֶה. וְאָמַר "הוֹכֵחַ תּוֹכִיחַ אֶת עֲמִיתֶךָ" - מִצְוָה אַחֶרֶת, לְלַמְּדוֹ תּוֹכַחַת מוּסָר. "וְלֹא תִשָּׂא עָלָיו חֵטְא" - שֶׁיִּהְיֶה עָלֶיךָ אָשָׁם כַּאֲשֶׁר יֶחֱטָא וְלֹא הֹכַחְתָּ אוֹתוֹ. וְלָזֶה יַטֶּה לְשׁוֹן אוּנְקְלוֹס (תרגום אונקלוס על ויקרא י"ט:י"ז) שֶׁאָמַר, "וְלָא תְקַבֵּל עַל דִּילֵהּ חוֹבָא", שֶׁלֹּא תְּקַבֵּל אַתָּה עֹנֶשׁ בַּחֵטְא שֶׁלּוֹ. וְאַחֲרֵי כֵּן צִוָּה שֶׁתֶּאֱהֹב אוֹתוֹ. וְהִנֵּה הַשּׂוֹנֵא אֶת רֵעֵהוּ עוֹבֵר בְּלָאו, וְהָאוֹהֵב לוֹ מְקַיֵּם עֲשֵׂה. וְהַנָּכוֹן בְּעֵינַי כִּי "הוֹכֵחַ תּוֹכִיחַ" כְּמוֹ "וְהוֹכִחַ אַבְרָהָם אֶת אֲבִימֶלֶךְ" (בראשית כא כה), וְיֹאמַר הַכָּתוּב אַל תִשְׂנָא אֶת אָחִיךָ בִּלְבָבֶךָ בַּעֲשׂוֹתוֹ לְךָ שֶׁלֹּא כִּרְצוֹנְךָ, אֲבָל תּוֹכִיחֶנּוּ, מַדּוּעַ כָּכָה עָשִׂיתָ עִמָּדִי, וְלֹא תִשָּׂא עָלָיו חֵטְא לְכַסּוֹת שִׂנְאָתוֹ בְּלִבְּךָ וְלֹא תַּגִּיד לוֹ, כִּי בְּהוֹכִיחֲךָ אוֹתוֹ יִתְנַצֵּל לְךָ אוֹ יָשׁוּב וְיִתְוַדֶּה עַל חֶטְאוֹ וּתְכַפֵּר לוֹ. וְאַחֲרֵי כֵן יַזְהִיר שֶׁלֹּא תִּנְקֹם מִמֶּנּוּ וְלֹא תִּטֹּר בִּלְבָבְךָ מַה שֶׁעָשָׂה לְךָ, כִּי יִתָּכֵן שֶׁלֹּא יִשְׂנָא אוֹתוֹ אֲבָל יִזְכֹּר הַחֵטְא בְּלִבּוֹ, וּלְפִיכָךְ יַזְהִירֶנּוּ שֶׁיִּמְחֶה פֶּשַׁע אָחִיו וְחַטָּאתוֹ מִלִּבּוֹ. וְאַחֲרֵי כֵן יְצַוֶּה שֶׁיֹּאהַב לוֹ כָּמוֹהוּ:
@18 וְטַעַם **וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ** הַפְלָגָה, כִּי לֹא יְקַבֵּל לֵב הָאָדָם שֶׁיֶּאֱהֹב אֶת חֲבֵרוֹ כְּאַהֲבָתוֹ אֶת נַפְשׁוֹ. וְעוֹד שֶׁכְּבָר בָּא רַבִּי עֲקִיבָא וְלִמֵּד, חַיֶּיךָ קוֹדְמִין לְחַיֵּי חֲבֵרְךָ (ב"מ סב). אֶלָּא מִצְוַת הַתּוֹרָה שֶׁיֹּאהַב חֲבֵרוֹ בְּכָל עִנְיָן כַּאֲשֶׁר יֹאהַב אֶת נַפְשׁוֹ בְּכָל הַטּוֹב. וְיִתָּכֵן בַּעֲבוּר שֶׁלֹּא אָמַר "וְאָהַבְתָּ אֶת רֵעֲךָ כָּמוֹךָ" וְהִשְׁוָה אוֹתָם בְּמִלַּת "לְרֵעֲךָ", וְכֵן "וְאָהַבְתָּ לוֹ כָּמוֹךָ" (ויקרא י"ט:ל"ד) דְּגֵר, שֶׁיִּהְיֶה פֵּרוּשׁוֹ לְהַשְׁווֹת אַהֲבַת שְׁנֵיהֶם בְּדַעְתּוֹ, כִּי פְּעָמִים שֶׁיֹּאהַב אָדָם אֶת רֵעֵהוּ בִּדְבָרִים יְדוּעִים, לְהֵטִיבוֹ בְּעֹשֶׁר וְלֹא בְּחָכְמָה וְכַיּוֹצֵא בָּזֶה, וְאִם יִהְיֶה אוֹהֲבוֹ בַּכֹּל, יַחְפֹּץ שֶׁיִּזְכֶּה רֵעֵהוּ הָאָהוּב לוֹ בְּעֹשֶׁר וּבִנְכָסִים וְכָבוֹד וּבְדַעַת וּבְחָכְמָה, וְלֹא שֶׁיִּשְׁוֶה אֵלָיו אֲבָל יִהְיֶה חָפֵץ בְּלִבּוֹ לְעוֹלָם שֶׁיִּהְיֶה הוּא יוֹתֵר מִמֶּנּוּ בְּכָל טוֹבָה. וִיצַוֶּה הַכָּתוּב שֶׁלֹּא תִּהְיֶה פְּחִיתוּת הַקִּנְאָה הַזֹּאת בְּלִבּוֹ, אֲבָל יֹאהַב בִּרְבוֹת הַטּוֹבָה לַחֲבֵרוֹ כַּאֲשֶׁר אָדָם עוֹשֶׂה לְנַפְשׁוֹ, וְלֹא יִתֵּן שִׁעוּרִין בָּאַהֲבָה. וְעַל כֵּן אָמַר בִּיהוֹנָתָן (שמואל א כ יז), "כִּי אַהֲבַת נַפְשׁוֹ אֲהֵבוֹ", בַּעֲבוּר שֶׁהֵסִיר מִדַּת הַקִּנְאָה מִלִּבּוֹ וְאָמַר (שם כג יז) "וְאַתָּה תִּמְלֹךְ עַל יִשְׂרָאֵל" וְגוֹ'. וְעִנְיַן הַנְּקִימָה וְהַנְּטִירָה כְּבָר פֵּרְשׁוּהוּ רַבּוֹתֵינוּ (תו"כ קדושים ד י יא), שֶׁהוּא בְּדָבָר שֶׁאֵין בּוֹ חִיּוּב מָמוֹן, הַשְׁאִילֵנִי מַגָּלְךָ, הַשְׁאִילֵנִי קַרְדֻּמְּךָ, כִּי בְּדָבָר שֶׁנִּתְחַיֵּב לוֹ חֲבֵרוֹ מָמוֹן כְּגוֹן בִּנְזִיקִין וְכַיּוֹצֵא בָּהֶן, אֵינוֹ מְחֻיָּב לְהַנִּיחַ לוֹ, אֲבָל יִתְבָּעֶנּוּ בְּב"ד וִישֻׁלַּם מִמֶּנּוּ, מִפָּסוּק "כַּאֲשֶׁר עָשָׂה כֵּן יֵעָשֶׂה לּוֹ" (ויקרא כ"ד:י"ט), וְהוּא מֵעַצְמוֹ חַיָּב לְשַׁלֵּם כַּאֲשֶׁר יְשַׁלֵּם מַה שֶׁלָּוָה אוֹ מַה שֶׁגָּזַל. וְכָל שֶׁכֵּן בְּעִנְיַן נֶפֶשׁ, שֶׁיִּהְיֶה נוֹקֵם וְנוֹטֵר לוֹ עַד שֶׁיִּגְאַל דְּמֵי אָחִיו מִיָּדוֹ עַל פִּי בֵּית דִּין הַמּוֹרִים בְּמִשְׁפְּטֵי הַתּוֹרָה:
@19 **אֶת חֻקֹּתַי תִּשְׁמֹרוּ** וְאֵלּוּ הֵן: "בְּהֶמְתְּךָ לֹא תַרְבִּיעַ כִּלְאַיִם" וְגוֹ'. חֻקִּים אֵלּוּ גְּזֵרוֹת מֶלֶךְ שֶׁאֵין טַעַם לַדָּבָר, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:י"ט). וְלֹא הִזְכִּירוּ רַבּוֹתֵינוּ שֶׁיִּהְיֶה הַטַּעַם נֶעְלָם, וְשֶׁיִּהְיוּ יֵצֶר הָרַע וְאֻמּוֹת הָעוֹלָם מְשִׁיבִים עֲלֵיהֶם, אֶלָּא בִּלְבִישַׁת שַׁעַטְנֵז, לֹא בְּכִלְאֵי הַבְּהֵמָה. וְאֵין הַכַּוָּנָה בָּהֶם שֶׁתִּהְיֶה גְּזֵרַת מֶלֶךְ מַלְכֵי הַמְּלָכִים בְּשׁוּם מָקוֹם בְּלֹא טַעַם, כִּי "כָּל אִמְרַת אֱלוֹהַּ צְרוּפָה" (משלי ל ה), רַק הַחֻקִּים הֵם גְּזֵרַת הַמֶּלֶךְ אֲשֶׁר יָחוֹק בְּמַלְכוּתוֹ בְּלִי שֶׁיְּגַלֶּה תּוֹעַלְתָּם לָעָם, וְאֵין הָעָם נֶהֱנִים בָּהֶם, אֲבָל מְהַרְהֲרִין אַחֲרֵיהֶם בְּלִבָּם וּמְקַבְּלִים אוֹתָם לְיִרְאַת הַמַּלְכוּת. וְכֵן חֻקֵּי הקב"ה הֵם הַסּוֹדוֹת אֲשֶׁר לוֹ בַּתּוֹרָה, שֶׁאֵין הָעָם בְּמַחְשַׁבְתָּם נֶהֱנִים בָּהֶם כַּמִּשְׁפָּטִים, אֲבָל כֻּלָּם בְּטַעַם נָכוֹן וְתוֹעֶלֶת שְׁלֵמָה. וְהַטַּעַם בַּכִּלְאַיִם, כִּי הַשֵּׁם בָּרָא הַמִּינִים בָּעוֹלָם בְּכָל בַּעֲלֵי הַנְּפָשׁוֹת, בַּצְּמָחִים, וּבְבַעֲלֵי נֶפֶשׁ הַתְּנוּעָה, וְנָתַן בָּהֶם כֹּחַ הַתּוֹלָדָה שֶׁיִּתְקַיְּמוּ הַמִּינִים בָּהֶם לָעַד כָּל זְמַן שֶׁיִּרְצֶה הוּא יִתְבָּרַךְ בְּקִיּוּם הָעוֹלָם. וְצִוָּה בְּכֹחָם שֶׁיּוֹצִיאוּ לְמִינֵיהֶם, וְלֹא יִשְׁתַּנּוּ לָעַד לְעוֹלָם, שֶׁנֶּאֱמַר בְּכֻלָּם "לְמִינֵהוּ" (בראשית א). וְהִנֵּה צִוָּה סִבַּת הַמִּשְׁכָּב שֶׁנַּרְבִּיעַ הַבְּהֵמוֹת זוֹ עִם זוֹ לְקִיּוּם הַמִּינִין כַּאֲשֶׁר יָבוֹאוּ הָאֲנָשִׁים עַל הַנָּשִׁים לִפְרִיָּה וּרְבִיָּה. וְהַמַּרְכִּיב שְׁנֵי מִינִין, מְשַׁנֶּה וּמַכְחִישׁ בְּמַעֲשֵׂה בְּרֵאשִׁית, כְּאִלּוּ יַחְשֹׁב שֶׁלֹּא הִשְׁלִים הקב"ה בְּעוֹלָמוֹ כָּל הַצֹּרֶךְ וְיַחְפֹּץ הוּא לַעֲזֹר בִּבְרִיאָתוֹ שֶׁל עוֹלָם, לְהוֹסִיף בּוֹ בְּרִיּוֹת. וְהַמִּינִים בְּבַעֲלֵי חַיִּים לֹא יוֹלִידוּ מִין מִשֶּׁאֵינוֹ מִינוֹ, וְגַם הַקְּרוֹבִים בַּטֶּבַע שֶׁיִּוָּלְדוּ מֵהֶם, כְּגוֹן הַפְּרָדִים, יִכָּרֵת זַרְעָם, כִּי הֵם לֹא יוֹלִידוּ. וְהִנֵּה מִצַּד שְׁנֵי הַדְּבָרִים הָאֵלֶּה פְּעֻלַּת הַהַרְכָּבָה בְּמִינִים דָּבָר נִמְאָס וּבָטֵל. וְגַם הַצְּמָחִים אֲשֶׁר יִתְרַכְּבוּ מִין בְּשֶׁאֵינוֹ מִינוֹ אֵין פִּרְיָם צוֹמֵחַ אַחֲרֵי כֵן, וְיִהְיֶה בְּאִסּוּרָם שְׁנֵי הַטְּעָמִים הַנִּזְכָּרִים. וְזֶה טַעַם "שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם", שֶׁהוּא בְּהַרְכָּבָה עַל דַּעַת רַבּוֹתֵינוּ (קידושין לט). וְאָסַר אַף כִּלְאֵי זְרָעִים, מִפְּנֵי שֶׁיִּשְׁתַּנּוּ בְּטִבְעָם גַּם בְּצוּרָתָם בִּהְיוֹתָם יוֹנְקִים זֶה מִזֶּה, וְיִהְיֶה כָּל גַּרְעִין מִמֶּנּוּ כְּאִלּוּ הֻרְכַּב מִשְּׁנֵי מִינִין. וְאָסוּר לַחֲרֹשׁ בְּשׁוֹר וּבַחֲמוֹר, מִפְּנֵי שֶׁדֶּרֶךְ כָּל עוֹבֵד אַדְמָתוֹ לְהָבִיא צִמְדּוֹ בְּרֶפֶת אַחַת וְיָבֹאוּ לִידֵי הַרְכָּבָה. וּמֵחֲבֵרֵינוּ מוֹסִיף בְּטַעַם הַכִּלְאַיִם כִּי הוּא שֶׁלֹּא לְעַרְבֵּב הַכֹּחוֹת הַמְגַדְּלִים הַצְּמָחִים לִהְיוֹת יוֹנְקִים זֶה מִזֶּה, מִמַּה שֶׁאָמְרוּ בִּבְרֵאשִׁית רַבָּה (בראשית רבה י':ו'), אָמַר רַבִּי סִימוֹן, אֵין לְךָ כָּל עֵשֶׂב וְעֵשֶׂב מִלְּמַטָּה שֶׁאֵין לוֹ מַזָּל בָּרָקִיעַ מִלְּמַעְלָה וּמַכֶּה אוֹתוֹ וְאוֹמֵר לוֹ גְּדַל, הֲדָא הוּא דִכְתִיב (איוב לח לג) "הֲיָדַעְתָּ חֻקּוֹת שָׁמָיִם אִם תָּשִׂים מִשְׁטָרוֹ בָאָרֶץ". וְהִנֵּה הַמַּרְכִּיב כִּלְאַיִם אוֹ זוֹרְעָן בִּכְדֵי שֶׁיִּינְקוּ זֶה מִזֶּה, מְבַטֵּל חֻקּוֹת שָׁמַיִם. וּלְכָךְ אָמַר בָּהֶם "אֶת חֻקֹּתַי תִּשְׁמֹרוּ", כִּי הֵם חֻקּוֹת שָׁמַיִם. וְכָךְ אָמַר רַבִּי חֲנִינָא מִשּׁוּם רַבִּי פִּנְחָס, מִשּׁוּם חֻקִּים שֶׁחָקַקְתִּי בָּהֶם אֶת עוֹלָמִי (ירושלמי כלאים פ"א ה"ז). וּכְבָר כָּתַבְתִּי בְּסֵדֶר בְּרֵאשִׁית (א כו) שֶׁהַצְּמָחִים כֻּלָּם יְסוֹדוֹתָם בָּעֶלְיוֹנִים, וּמִשָּׁם צִוָּה לָהֶם הַשֵּׁם אֶת הַבְּרָכָה חַיִּים עַד הָעוֹלָם, וְהִנֵּה הַמְּעָרֵב כִּלְאַיִם מַכְחִישׁ וּמְעָרֵב מַעֲשֵׂה בְּרֵאשִׁית:
@19 **וּבֶגֶד כִּלְאַיִם שַׁעַטְנֵז** לָמָּה נֶאֱמַר, לְפִי שֶׁנֶּאֱמַר (דברים כב יא) "לֹא תִלְבַּשׁ שַׁעַטְנֵז צֶמֶר וּפִשְׁתִּים יַחְדָּו", יָכוֹל לֹא יִלְבַּשׁ גִּזֵּי צֶמֶר וַאֲנִיצֵי פִשְׁתָּן, תַּלְמוּד לוֹמַר "בֶּגֶד". מִנַּיִן לְרַבּוֹת אֶת הַלְּבָדִים, תַּלְמוּד לוֹמַר "שַׁעַטְנֵז" - דָּבָר שֶׁהוּא שׁוּעַ טָווּי וְנוּז. וְאוֹמֵר אֲנִי "נוּז" לְשׁוֹן דָּבָר הַנִּמְלָל וְשָׁזוּר זֶה עִם זֶה לְחַבְּרוֹ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:י"ט). וְאֵינוֹ נָכוֹן בְּעֵינַי, שֶׁהַלְּבָדִים אֵין אִסּוּרָם מִדִּבְרֵי תוֹרָה אֶלָּא מִדִּבְרֵי סוֹפְרִים, שֶׁאֵינָן אֶלָּא שׁוּעַ בִּלְבַד, וְכָךְ שָׁנִינוּ (כלאים פ"ט מ"ט), הַלְּבָדִים אֲסוּרִין מִפְּנֵי שֶׁהֵן שׁוּעַ. וּבַגְּמָרָא אָמְרוּ (נדה סא), וְאֵימָא אוֹ שׁוּעַ אוֹ טָווּי אוֹ נוּז, וְהֶעֱלוּ וְהִלְכְתָא כְּמָר זוּטְרָא מִדְּאַפְּקִינְהוּ רַחֲמָנָא בְּחַד לִישָׁנָא. אֲבָל הַבָּרַיְתָא הַשְּׁנוּיָה בְּתוֹרַת כֹּהֲנִים (פרק ד יח), אֵין לִי אֶלָּא בֶּגֶד, וּמִנַּיִן לְרַבּוֹת הַלְּבָדִים, תַּלְמוּד לוֹמַר "שַׁעַטְנֵז", בָּא לְרַבּוֹת הַדְּבָרִים שֶׁאֵינָן בֶּגֶד מִ"לֹּא תִלְבַּשׁ שַׁעַטְנֵז", שֶׁלֹּא הֻזְכַּר בֶּגֶד. וְהַמִּדְרָשׁ הוּא עִקָּר, שֶׁאֲפִלּוּ דָּבָר שֶׁאֵינוֹ בֶּגֶד אָסוּר בְּכִלְאַיִם מִן הַתּוֹרָה, כְּגוֹן הַקּוֹלֵעַ חוּטִין וְעֹשֶׂה מֵהֶן חֲגוֹרָה וְכַיּוֹצֵא בָּזֶה, וּבִלְבַד שֶׁיְּהֵא שׁוּעַ וְטָווּי וְנוּז. וְתָפַס לוֹ הַלְּבָדִים לְאַסְמַכְתָּא בְּעָלְמָא, שֶׁהֵם אֲסוּרִים מִדִּבְרֵיהֶם וְאֵינָן בֶּגֶד. וְכֵן מַה שֶׁפֵּרֵשׁ הָרַב בְּ"שׁוּעַ", שֶׁהוּא דָּבָר הַנִּמְלָל וְשָׁזוּר זֶה עִם זֶה, וְכַפֵּרוּשׁ הַזֶּה כָּתַב עוֹד בְּפֵרוּשָׁיו בַּגְּמָרָא (יבמות ה נדה סא), כְּבָר הֵשִׁיבוּ עָלָיו שֶׁאֵין פֵּרוּשׁוֹ עוֹלֶה מִמַּה שֶׁאָמְרוּ (מנחות לט) שְׁמַע מִנָּה קֶשֶׁר הָעֶלְיוֹן בְּצִיצִית דְּאוֹרָיְתָא, דְּאִי סָלְקָא דַעְתָּךְ לָאו דְּאוֹרָיְתָא, כִּלְאַיִם דִּשְׁרָא רַחֲמָנָא בְּצִיצִית לָמָּה לִי, הָא קַיְמָא לַן הַתּוֹכֵף תְּכִיפָה אַחַת אֵינוֹ חִבּוּר. וְהִנֵּה גִּלּוּ לָנוּ שֶׁהַבֶּגֶד שֶׁהוּא מִין פִּשְׁתִּים וְנִקְשֹׁר בּוֹ צִיצִית שֶׁל צֶמֶר בִּשְׁנֵי קְשָׁרִים הוּא כִּלְאַיִם מִן הַתּוֹרָה, אע"פ שֶׁאֵינוֹ נִמְלָל וְשָׁזוּר זֶה עִם זֶה. אֲבָל הָעִנְיָן כָּךְ הוּא, שֶׁאָמַר הַכָּתוּב "וּבֶגֶד כִּלְאַיִם שַׁעַטְנֵז" לוֹמַר שֶׁכָּל בֶּגֶד הַנַּעֲשֶׂה מִחוּט שֶׁהוּא שׁוּעַ וְטָווּי וְשָׁזוּר לֹא נִלְבַּשׁ אוֹתוֹ כִּלְאַיִם, שֶׁהוּא עֵרוּבִים, וּבְמִשְׁנֵה תּוֹרָה (דברים כב יא) הוֹסִיף לְבָאֵר שֶׁלֹּא נִלְבַּשׁ שׁוּעַ טָווּי וְנוּז מִצֶּמֶר וּפִשְׁתִּים שֶׁיִּהְיוּ "יַחְדָּו", כְּלוֹמַר מְחֻבָּרִים יַחַד בִּשְׁתֵּי תְּכִיפוֹת, לוֹמַר שֶׁהַצֶּמֶר וְהַפִּשְׁתִּים שֶׁכָּל מִין מֵהֶם שׁוּעַ טָווּי וְנוּז בִּפְנֵי עַצְמוֹ לֹא נְחַבְּרֵם יַחְדָּו, כִּי "יַחְדָּו" הוּא הַכִּלְאַיִם, כְּמוֹ שֶׁאָמַר (דברים כב י) "לֹא תַחֲרֹשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו", כְּלוֹמַר קְשׁוּרִים וּמְחֻבָּרִים, וְהַחִבּוּר בִּבְגָדִים בִּשְׁתֵּי תְּכִיפוֹת, כִּי מִלְּשׁוֹן "יַחְדָּו" לָמְדוּ כֵן כִּי שְׁתֵּי תְּכִיפוֹת הֵן חִבּוּר, וּמִשָּׁם לָמְדוּ שֶׁהַכִּלְאַיִם אֲסוּרִין אע"פ שֶׁאֵינָן בֶּגֶד אֶלָּא אֲפִלּוּ בְּקוֹלֵעַ הַחוּטִין מַעֲשֵׂה עֲבוֹת וְעֹשֶׂה מֵהֶן אַבְנֵטִים, אַף עַל פִּי שֶׁאֵינוֹ אָרוּג, וּכְעִנְיָן שֶׁשָּׁנִינוּ (כלאים פ"ט מ"ט) לֹא יִקְשֹׁר סֶרֶט שֶׁל צֶמֶר בְּשֶׁל פִּשְׁתָּן לַחְגֹּר בּוֹ אֶת מָתְנָיו. וּלְשׁוֹן "נוּז" מִלָּה מְקֻצֶּרֶת בַּתֵּבָה הַמֻּרְכֶּבֶת הַזֹּאת, כְּמוֹ הַטָּווּי שֶׁאֵין מִמֶּנּוּ בָּהּ אֶלָּא הַטֵּי"ת, וְעִנְיָנָהּ לְפִי דַּעְתִּי נָלוֹז, מִלְּשׁוֹן "תּוֹעֲבַת ה' נָלוֹז" (משלי ג לב), מַטֶּה וּמְעַקֵּם דְּרָכָיו, "וּנְלוֹזִים בְּמַעְגְּלוֹתָם" (שם ב טו), פְּתַלְתֻּלִּים וּמַטִּים, כִּי כֵן הַדָּבָר הַשָּׁזוּר פָּתוּל וּמְעֻקָּם. וּכְמוֹ שֶׁשָּׁנִינוּ (כלאים פ"ט מ"ח), רַבִּי שִׁמְעוֹן אוֹמֵר נָלוֹז וּמַלִּיז אָבִיו שֶׁבַּשָּׁמַיִם עָלָיו, מַטֶּה הַשֵּׁם הַנִּכְבָּד מִדַּרְכֵי רַחֲמָיו עָלָיו, כְּעִנְיָן שֶׁנֶּאֱמַר "וְעִם עִקֵּשׁ תִּתְפַּתָּל" (תהלים יח כז). וּבִלְשׁוֹן חֲכָמִים יְשַׁמְּשׁוּ בּוֹ בְּקֹצֶר, לְבֶן מְלָכִים שֶׁנּוּז לִבּוֹ עָלָיו, וְנָטַל אֶת הַצִּפֹּרֶן לַחְתֹּר עַל אָבִיו (שמו"ר לז ב), שֶׁנָּטָה לִבּוֹ לְדֶרֶךְ רָעָה. וּמִזֶּה אָמְרוּ בְּתַלְמוּד סַנְהֶדְרִין (מא), מִנָּזְיָתֵהּ דְּמַר לָא אָמְרִי בֵּהּ וְלָא מִידִי, כְּלוֹמַר אִם הָיִיתָ רוֹצֶה לְהִתְעַקֵּם וּלְהַטּוֹת הַדְּבָרִים לֹא הָיִינוּ יוֹדְעִים לְנֶגְדְּךָ כְּלוּם, "נָזְיָיתֵהּ" כְּמוֹ "נַלְזְיָתֵהּ", כְּלוֹמַר הַטָּיָתוֹ. וְזֶהוּ הָאֱמֶת וְהַנָּכוֹן בָּעִנְיָן הַזֶּה. וּלְפִיכָךְ הֻצְרַךְ לְהַתִּיר כִּלְאַיִם בְּצִיצִית אע"פ שֶׁאֵין הַצִּיצִית אָרוּג וְאֵינוֹ בֶּגֶד. וְזֶהוּ דִּין תּוֹרָה, אֲבָל חֲכָמִים אָסְרוּ אֲפִלּוּ מַה שֶׁאֵינוֹ עָשׂוּי אֶלָּא בְּאֶחָד מֵהֶם, אוֹ שׁוּעַ אוֹ טָווּי אוֹ נוּז, וּלְפִיכָךְ שָׁנִינוּ (כלאים ט ט), הַלְּבָדִים אֲסוּרִין מִפְּנֵי שֶׁהֵן שׁוּעִים, פִּיף שֶׁל צֶמֶר בְּשֶׁל פִּשְׁתָּן אֲסוּרִין מִפְּנֵי שֶׁהֵן חוֹגְרִין בְּאָרִיג, וְהַכֹּל מִדְּרַבָּנָן. וְטַעַם כִּלְאֵי הַבְּגָדִים לְהַרְחִיק הַתַּעֲרוֹבוֹת בְּמִינִין, וְאָסַר הָרְגִילִים לְהֵעָשׂוֹת מֵהֶן בֶּגֶד. וְהָרַב אָמַר בְּמוֹרֶה הַנְּבֻכִים (ג לז) טַעַם הַשַּׁעַטְנֵז, מִפְּנֵי שֶׁהָיָה בַּזְּמַן הַהוּא בֶּגֶד יָדוּעַ לְכָמְרֵי בַּעֲלֵי הַכְּשָׁפִים שֶׁבָּהֶם הָיוּ עוֹשִׂים כָּל מַעֲשֵׂיהֶם. וְאָמַר שֶׁמָּצָא זֶה כָּתוּב בְּסִפְרֵיהֶם. וּלְפִי שֶׁהָיָה עִנְיָן גָּדוֹל וְרָצוּי לָהֶם מְאֹד שֶׁיִּפְעֲלוּ בּוֹ פְּעֻלּוֹתָם הַיְּדוּעוֹת לַעֲבוֹדָה זָרָה וְלַשֵּׁדִים, תַּרְחִיק אוֹתוֹ הַתּוֹרָה מִכָּל אָדָם, כִּי הַתּוֹרָה תָּבֹא לִמְחוֹת מַעֲשֵׂיהֶם וּלְהַכְחִיד זִכְרָם:
@20 **וְהִיא שִׁפְחָה נֶחֱרֶפֶת לְאִישׁ** מְיֹעֶדֶת לְאִישׁ, וְאֵינִי יוֹדֵעַ לוֹ דִמְיוֹן בַּמִּקְרָא, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:כ'). וְהַנִּרְאֶה אֵלַי כִּי הוּא מִלְּשׁוֹן "כַּאֲשֶׁר הָיִיתִי בִּימֵי חָרְפִּי" (איוב כט ד) - "בִּימֵי נְעוּרַי", וְכֵן "לֹא יֶחֱרַף לְבָבִי מִיָּמָי" (שם כז ו), שֶׁלֹּא יִהְיֶה לִי לֵב נַעַר, וְיִקָּרְאוּ יְמֵי הַנְּעוּרִים יְמֵי חֹרֶף, כִּי הַחֹרֶף בְּרֵאשִׁית הַשָּׁנִים, וִימֵי הַזִּקְנָה כְּנֶגֶד הַקַּיִץ שֶׁהֵם יְמֵי הָאָסִיף. יֹאמַר הַכָּתוּב שֶׁהִיא שִׁפְחָה נַעֲרָה לְאִישׁ יָדוּעַ, כִּי הַפִּילֶגֶשׁ אֲשֶׁר הִיא מְשָׁרֵת אֶת הָאִישׁ וְיִשְׁכַּב עִמָּהּ תִּקָּרֵא נַעֲרָה לוֹ, כִּי גַּם כָּל מְשָׁרֵת הָאָדָם יִקָּרֵא נַעֲרוֹ. וּמֻרְגָּל בִּלְשׁוֹן חֲכָמִים לֵאמֹר עַל הַשּׁוֹכֶבֶת עִם הָאִישׁ - מְשַׁמֶּשֶׁת עִמּוֹ. וְהִיא נֶחֱרֶפֶת, שֶׁנַּעֲשֵׂית נַעֲרָה לְאִישׁ וִידוּעָה לוֹ, מסיפד"ה בְּלַעַ"ז. וְכֵן בִּלְשׁוֹן חֲכָמִים (סנהדרין נח), דְּקָרוּ לָהּ רָבִיתָא דִּפְלָנְיָא. וְהָעִנְיָן שֶׁאֵינָהּ אִשְׁתּוֹ לְגַמְרֵי, אֲבָל נָתַן לָהּ קִדּוּשִׁין וְהִיא לוֹ לְנַעֲרָה מְשַׁמֶּשֶׁת:
@20 **בִּקֹּרֶת תִּהְיֶה** יֵשׁ עַל בֵּית דִּין לְבַקֵּר הַדָּבָר שֶׁלֹּא לְחַיְּבוֹ מִיתָה, "כִּי לֹא חֻפָּשָׁה" וְאֵין קִדּוּשֶׁיהָ גְּמוּרִין, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:כ'). וְכֵן אָמְרוּ כָּל הַמְפָרְשִׁים. וְאִם כֵּן יַזְהִיר הַכָּתוּב בַּבִּקּוּר הַזֶּה מִפְּנֵי שֶׁהִיא דּוֹמָה לְאֵשֶׁת אִישׁ, אוּלַי יִטְעוּ בָּהּ. וְאֵין פֵּרוּשָׁם מָתוֹק בְּפִי, כִּי בְּיָדוּעַ שֶׁיְּבֻקַּר הַדָּבָר וְלֹא יָמִיתוּ הָאָדָם חִנָּם, וְכֵן יְבַקְּרוּ בְּכָל חַיָּבֵי הַמִּיתוֹת. וַאֲנִי סוֹבֵר שֶׁהִיא מִלָּה יְחִידִית בַּכָּתוּב, אֲבָל הִיא מֻרְגֶּלֶת בִּלְשׁוֹן אֲרַמִּית, וּבְדִבְרֵי רַבּוֹתֵינוּ מִלְּשׁוֹן "הֶפְקֵר", כִּי עִקַּר הַלָּשׁוֹן "הֶבְקֵר", כְּמוֹ שֶׁאָמְרוּ (פאה פ"ו מ"א), בֵּית שַׁמַּאי אוֹמְרִים הֶבְקֵר לָעֲנִיִּים הֶבְקֵר, וּבֵית הִלֵּל אוֹמְרִים עַד שֶׁיַּבְקִיר אַף לָעֲשִׁירִים כַּשְּׁמִטָּה. וּתְנַן נָמֵי (שביעית פ"ט מ"ד), אוֹכְלִין עַל הַמֻּבְקָר אֲבָל לֹא עַל הַשָּׁמוּר. וְתִרְגֵּם יוֹנָתָן "אֲנָשִׁים רֵקִים וּפֹחֲזִים" (שופטים ט ד) - "סְרִיקִין וּבָקְרִין", כְּלוֹמַר בַּעֲלֵי הֶבְקֵר, "בְּשִׁקְרֵיהֶם וּבְפַחֲזוּתָם" (ירמיהו כג לב) - "וּבַקָּרוּתְהוֹן". וְאָמְרוּ כִּי "תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ" (שמות כג יא) תַּרְגּוּם יְרוּשַׁלְמִי "וּתְבַקְּרִנַּהּ". וְכֵן בְּכָל מָקוֹם בַּמִּשְׁנָה הַלָּשׁוֹן בְּבֵי"ת, אֲבָל הִרְגִּילוּ בַּגְּמָרָא לוֹמַר מִמֶּנּוּ "הֶפְקֵר", כִּי הָאוֹתִיּוֹת הָאֵלֶּה מִתְחַלְּפוֹת אֶצְלָם תָּמִיד, כַּאֲשֶׁר אוֹמְרִים (פסחים מה) מִן "עָבְשׁוּ פְרוּדוֹת" (יואל א יז) - "עִפּוּשׁ". וְכֵן בַּכָּתוּב בִּמְקוֹמוֹת הַרְבֵּה, כְּמוֹ שֶׁהִזְכַּרְתִּי בְּפָסוּק "נָשַׁפְתָּ בְּרוּחֲךָ" (שמות טו י). וּפֵרוּשׁ הַפָּסוּק הַזֶּה שֶׁאָמַר בַּשִּׁפְחָה הַזֹּאת, אע"פ שֶׁהִיא נֶחֱרֶפֶת לְאִישׁ לֹא תִּהְיֶה לוֹ לְאִשָּׁה, כִּי בִּקֹּרֶת תִּהְיֶה לוֹ, כְּלוֹמַר מֻפְקֶרֶת תֵּחָשֵׁב אֶצְלוֹ, וְלֹא יוּמְתוּ כְּמִשְׁפַּט הַנּוֹאֵף וְהַנּוֹאֶפֶת בְּאֵשֶׁת אִישׁ, כִּי לֹא חֻפָּשָׁה לִהְיוֹת אִשְׁתּוֹ גְּמוּרָה, אֲבָל יָבִיא זֶה עָלֶיהָ אָשָׁם בַּעֲבוּר שֶׁהִיא נֶחֱרֶפֶת אֵלָיו. וְאוּנְקְלוֹס (תרגום אונקלוס על ויקרא י"ט:כ') שֶׁאָמַר "בִּקֻּרְתָּא תְּהֵא", לְשׁוֹנוֹ כִּלְשׁוֹן יוֹנָתָן בֶּן עֻזִּיאֵל (שופטים ט ד) בְּמִלַּת "בָּקְרִין":
@23 **וַעֲרַלְתֶּם עָרְלָתוֹ אֶת פִּרְיוֹ** וַאֲטַמְתֶּם אֲטִימָתוֹ, יְהֵא אָטוּם וְנִסְתָּר מִלֵּהָנוֹת בּוֹ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:כ"ג). וְיָפֶה פֵּרֵשׁ. וְאִם כֵּן יִהְיֶה "עֲרַל לֵב" (יחזקאל מד ט) - סְגוּר לֵב, כְּמוֹ שֶׁנֶּאֱמַר "וְאֶקְרַע סְגוֹר לִבָּם" (הושע יג ח). וְכֵן "עֲרֵלָה אָזְנָם" (ירמיהו ו י) - שֶׁהִיא סְגוּרָה וַאֲטוּמָה, אֵין הַקּוֹל נִכְנָס בָּהּ. וַ"עֲרַל שְׂפָתָיִם" (שמות ו יב) - סְגוּר שְׂפָתַיִם, כִּי הָעִלְּגוּת אֹטֶם וּסְגִירוּת בְּגִידֵי הַלָּשׁוֹן, וּפְעָמִים בְּגִידֵי הַשְּׂפָתַיִם שֶׁלֹּא יִפָּתְחוּ כָּרָאוּי; וְהַדִּבּוּר יִקָּרֵא פְּתִיחָה, "פְּתַח פִּיךָ לְאִלֵּם" (משלי לא ח), "פָּתַח אִיּוֹב אֶת פִּיהוּ" (איוב ג א), "וּמִפְתַּח שְׂפָתַי מֵישָׁרִים" (משלי ח ו), "מִשֹּׁכֶבֶת חֵיקֶךָ שְׁמֹר פִּתְחֵי פִיךָ" (מיכה ז ה). וְהִזְכִּיר הַכָּתוּב אֲטִימוּת בַּפְּרִי הַבָּא בְּתוֹךְ שָׁלֹשׁ שָׁנִים, לְאָסְרוֹ בַּהֲנָאָה. וְלֹא יֹאמַר כֵּן בִּשְׁאָר אִסּוּרֵי הֲנָאָה, כִּי בִּיאַת הַפְּרִי בִּתְחִלָּתוֹ יִקָּרֵא פְּתִיחָה, כְּמוֹ שֶׁאָמַר "פִּתַּח הַסְּמָדַר" (שיר השירים ז יג). וּלְכָךְ אָמַר "שָׁלֹשׁ שָׁנִים יִהְיֶה לָכֶם עֲרֵלִים", כְּאִלּוּ הַפֵּרוֹת סְגוּרִים בָּאִילָנוֹת, לֹא הוֹצִיאוּ פֶּרַח וְלֹא פִּתְּחוּ סְמָדַר. וְטַעַם הַמִּצְוָה הַזֹּאת, לְכַבֵּד אֶת ה' מֵרֵאשִׁית כָּל תְּבוּאָתֵנוּ מִפְּרִי הָעֵץ וּתְבוּאַת הַכֶּרֶם, וְלֹא נֹאכַל מֵהֶם עַד שֶׁנָּבִיא כָּל פְּרִי שָׁנָה אַחַת הִלּוּלִים לַה'. וְהִנֵּה אֵין הַפְּרִי בְּתוֹךְ שָׁלֹשׁ שָׁנִים רָאוּי לְהַקְרִיבוֹ לִפְנֵי הַשֵּׁם הַנִּכְבָּד, לְפִי שֶׁהוּא מוּעָט, וְאֵין הָאִילָן נוֹתֵן בְּפִרְיוֹ טַעַם אוֹ רֵיחַ טוֹב בְּתוֹךְ שָׁלֹשׁ שָׁנִים, וְרֻבָּן לֹא יוֹצִיאוּ פֵּרוֹת כְּלָל עַד הַשָּׁנָה הָרְבִיעִית. וּלְכָךְ נַמְתִּין לְכֻלָּן וְלֹא נִטְעֹם מֵהֶם עַד שֶׁנָּבִיא מִן הַנֶּטַע שֶׁנָּטַעְנוּ כָּל פִּרְיוֹ הָרִאשׁוֹן הַטּוֹב קֹדֶשׁ לִפְנֵי הַשֵּׁם, וְשָׁם יֹאכְלוּהוּ וִיהַלְלוּ אֶת שֵׁם ה'. וְהַמִּצְוָה הַזֹּאת דּוֹמָה לְמִצְוַת הַבִּכּוּרִים. וֶאֱמֶת הַדָּבָר עוֹד כִּי הַפְּרִי בִּתְחִלַּת נְטִיעַת הָאִילָנוֹת רַב הַלַּחוּת, דָּבֵק מְאֹד, מַזִּיק לַגּוּף וְאֵינֶנּוּ טוֹב לְאָכְלָה, כְּדָג שֶׁאֵין לוֹ קַשְׂקֶשֶׂת (ויקרא י"א:ט'), וְהַמַּאֲכָלִים הַנֶּאֱסָרִים בַּתּוֹרָה הֵם רָעִים גַּם לַגּוּף. וְהָרַב נָתַן גַּם בָּזֶה טַעַם בְּמוֹרֶה הַנְּבֻכִים (ג לז) כְּטַעְמוֹ בְּרוֹב הַמִּצְוֹת, כִּי הָיוּ לַחַרְטֻמִּים וְלַמְּכַשְּׁפִים בַּזְּמַן הַהוּא מִינֵי כִּשּׁוּף יַעֲשׂוּ אוֹתָם בְּעֵת נְטִיעַת הָאִילָנוֹת, וְיַחְשְׁבוּ כִּי בָּהֶם יְמַהֵר הָאִילָן לְהוֹצִיא פִּרְיוֹ קֹדֶם זְמַנּוֹ הַיָּדוּעַ בְּמִנְהָגוֹ שֶׁל עוֹלָם, וּבְבוֹאוֹ יַקְרִיבוּ אֶת הַפְּרִי לִפְנֵי הָעֲבוֹדָה זָרָה שֶׁעָשׂוּ בִּשְׁמָהּ הַכִּשּׁוּף הַהוּא. וּלְכָךְ צִוְּתָה הַתּוֹרָה בְּאִסּוּר הַפְּרִי הַבָּא קֹדֶם שָׁלֹשׁ שָׁנִים, שֶׁלֹּא יָבֹאוּ לַעֲשׂוֹת הַמַּעֲשִׂים הָרָעִים הָהֵם, כִּי רֻבֵּי הָאִילָנוֹת יָבִיאוּ פֵּרוֹת בַּשָּׁנָה הָרְבִיעִית; וְשֶׁנֹּאכְלֵהוּ לִפְנֵי הַשֵּׁם, הֵפֶךְ אָכְלָם אוֹתוֹ לִפְנֵי עֲבוֹדָה זָרָה:
@26 **לֹא תֹאכְלוּ עַל הַדָּם** לְהַרְבֵּה פָנִים נִדְרָשׁ בְּסַנְהֶדְרִין (סג), לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:כ"ו). וְהָעוֹלֶה מִשָּׁם לְפִי הַסֻּגְיָא שֶׁהֵם כֻּלָּם מִן הַתּוֹרָה, שֶׁכָּלַל הַכָּתוּב כָּל אֲכִילַת הַדָּם בְּלָאו אֶחָד. וְאִם כֵּן מַה שֶׁאָמַר הַכָּתוּב בְּשָׁאוּל (שמואל א יד לג) "הִנֵּה הָעָם חֹטִאים לַה' לֶאֱכֹל עַל הַדָּם" - שֶׁהָיוּ חוֹטְאִים בְּאֶחָד מִן הַשֵּׁמוֹת הַנִּכְלָלִים בַּלָּאו הַזֶּה, כִּי הָיוּ אוֹכְלִים מִן הַבְּהֵמָה קֹדֶם שֶׁתֵּצֵא נַפְשָׁהּ. זֶהוּ מַה שֶׁאָמַר (שם פסוק לב) "וַיַּעַט הָעָם אֶל הַשָּׁלָל", שֶׁהוּא כְּעַיִט הַדּוֹרֵס וְאוֹכֵל, "וַיִּקְחוּ צֹאן וּבָקָר וְגוֹ' וַיִּשְׁחֲטוּ אָרְצָה וַיֹּאכַל הָעָם עַל הַדָּם" מֵרֹב הַשָּׁלָל בַּבְּהֵמוֹת, כְּשֶׁהָיוּ שׁוֹפְכִים דָּמָם אַרְצָה הָיוּ תּוֹלְשִׁים אֶבְרֵיהֶם וְאוֹכְלִים קֹדֶם שֶׁיָּמוּתוּ. וְעַל דֶּרֶךְ הַפְּשָׁט הוּא מִין מִמִּינֵי הַכִּשּׁוּף אוֹ הַקְּסָמִים, כִּי הוּא דָּבָר לָמֵד מֵעִנְיָנוֹ, וְהָיוּ שׁוֹפְכִים הַדָּם וּמְאַסְּפִים אוֹתוֹ בְּגֻמָּא, וְהַשֵּׁדִים מִתְקַבְּצִים שָׁם כְּפִי דַּעְתָּם וְאוֹכְלִין עַל שֻׁלְחָנָן, לְהַגִּיד לָהֶם הָעֲתִידוֹת. וְכַאֲשֶׁר הָיוּ יִשְׂרָאֵל עִם שָׁאוּל בַּמַּחֲנֶה הַהוּא הָיוּ מִתְפַּחֲדִים מְאֹד מִן הַפְּלִשְׁתִּים, וְלֹא הָיָה שָׁאוּל עוֹשֶׂה דָּבָר בִּלְתִּי שְׁאֵלַת אוּרִים וְתֻמִּים, כְּמוֹ שֶׁנֶּאֱמַר (שם פסוק לו) "נִקְרְבָה הֲלֹם אֶל הָאֱלֹהִים", וְהָעָם הָיוּ שׁוֹאֲלִים בְּשֵׁדִים אוֹ בִּכְשָׁפִים לָדַעַת דַּרְכָּם וּמַעֲשֵׂיהֶם, וְאוֹכְלִים עַל הַדָּם לַעֲשׂוֹת הַמַּעֲשֶׂה הַהוּא. וּלְכָךְ אָמַר הַכָּתוּב (שם פסוק לג) "וַיַּגִּידוּ לְשָׁאוּל לֵאמֹר הִנֵּה הָעָם חֹטִאים לַה' לֶאֱכֹל עַל הַדָּם וַיֹּאמֶר בְּגַדְתֶּם", לוֹמַר הִנֵּה הַשֵּׁם עָשָׂה לָכֶם תְּשׁוּעָה גְּדוֹלָה הַיּוֹם וְאַתֶּם שׁוֹאֲלִים לְלֹא אֱלֹהִים, בְּגִידָה הִיא זוֹ. וְעוֹד אֲפָרֵשׁ אִסּוּר מְעוֹנֵן וּמְנַחֵשׁ (דברים יח ט):
@29 **אַל תְּחַלֵּל אֶת בִּתְּךָ לְהַזְנוֹתָהּ** בְּמוֹסֵר בִּתּוֹ פְּנוּיָה שֶׁלֹּא לְשֵׁם קִדּוּשִׁין. **וְלֹא תִזְנֶה הָאָרֶץ** אִם אַתָּה עוֹשֶׂה כֵן הָאָרֶץ מְזַנָּה אֶת פֵּרוֹתֶיהָ לַעֲשׂוֹתָם בְּמָקוֹם אַחֵר וְלֹא בְּאַרְצְכֶם. וְכֵן הוּא אוֹמֵר (ירמיהו ג ג) "וַיִּמָּנְעוּ רְבִבִים וּמַלְקוֹשׁ לוֹא הָיָה וּמֵצַח אִשָּׁה זוֹנָה הָיָה לָךְ" וְגוֹ', לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:כ"ט). וְלֹא הֲבִינוֹתִי דַּעְתּוֹ, שֶׁאֵין זְנוּת בַּתּוֹרָה בִּפְנוּיָה, שֶׁהֲלָכָה פְּסוּקָה הִיא (יבמות סא), פָּנוּי הַבָּא עַל פְּנוּיָה שֶׁלֹּא לְשֵׁם אִישׁוּת לֹא עֲשָׂאָהּ זוֹנָה. וּמְפֹרָשׁ אָמְרוּ בְּסַנְהֶדְרִין (נ), "וּבַת אִישׁ כֹּהֵן כִּי תֵחֵל לִזְנוֹת" (ויקרא כ"א:ט'), יָכוֹל אֲפִילּוּ פְּנוּיָה, וְהִקְשׁוּ, וְהָא "לִזְנוֹת" כְּתִיב, וְתֵרְצוּ, כְּרַבִּי אֱלִיעֶזֶר דַּאֲמַר פָּנוּי הַבָּא עַל הַפְּנוּיָה שֶׁלֹּא לְשֵׁם אִישׁוּת עֲשָׂאָהּ זוֹנָה. וְכֵן אָמְרוּ "אִשָּׁה זֹנָה וַחֲלָלָה לֹא יִקָּחוּ" (להלן כא ז), שֶׁאֵינוֹ בִּפְנוּיָה אֶלָּא גִּיּוֹרֶת וּמְשֻׁחְרֶרֶת אוֹ שֶׁנִּבְעֲלָה בְּעִילַת זְנוּת מִמִּי שֶׁאֵין קִדּוּשִׁין תּוֹפְסִין בָּהּ, כְּמוֹ שֶׁמְּפֹרָשׁ בִּיבָמוֹת (שם). וּבְסִפְרָא (אמור פרק א ז), "אִשָּׁה זוֹנָה" ר' יְהוּדָה אוֹמֵר זוֹ אַיְלוֹנִית, וַחֲכָמִים אוֹמְרִים אֵין זוֹנָה אֶלָּא הַגִּיּוֹרֶת וּמְשֻׁחְרֶרֶת וְשֶׁנִּבְעֲלָה בְּעִילַת זְנוּת, ר' אֱלִיעֶזֶר אוֹמֵר אַף פָּנוּי הַבָּא עַל הַפְּנוּיָה שֶׁלֹּא לְשֵׁם אִישׁוּת. וְכָךְ אָמְרוּ (תמורה כט) לְעִנְיַן "לֹא תָבִיא אֶתְנַן זוֹנָה" (דברים כג יט) שֶׁאֵינוֹ בִּפְנוּיָה כְּלָל. אֲבָל הַבָּרַיְתָא הַשְּׁנוּיָה בְּת"כ (פרק ז א) וְהַנִּזְכֶּרֶת בְּמַסֶּכֶת סַנְהֶדְרִין (סנהדרין ע"ו) אוֹ שֶׁהִיא כְּרַבִּי אֱלִיעֶזֶר וְאֵינָהּ הֲלָכָה, אוֹ שֶׁהִיא בְּמוֹסֵר אֶת בִּתּוֹ לְמִי שֶׁאֵין לוֹ אִישׁוּת, כְּגוֹן כּוּתִי וְעֶבֶד וְחַיָּבֵי כָּרֵתוֹת וּמִיתוֹת בֵּית דִּין, שֶׁזֶּה נִקְרָא זְנוּת לְדַעַת חֲכָמִים. וְזֶהוּ שֶׁאָמְרוּ, בְּמוֹסֵר אֶת בִּתּוֹ פְּנוּיָה שֶׁלֹּא לְשֵׁם אִישׁוּת, כְּלוֹמַר לְמִי שֶׁאִי אֶפְשָׁר לִהְיוֹת אִישׁוּת בֵּינֵיהֶם. וְכֵן מַה שֶׁשָּׁנִינוּ שָׁם בְּסִפְרָא (שם ז ב), "וְלֹא תִזְנֶה הָאָרֶץ", מְזַנִּים הֵם הַפֵּרוֹת, וְהוּא דֶּרֶךְ אַגָּדָה, נִדְרָשׁ מִמִּלַּת "הָאָרֶץ", מִדְּלָא כְּתִיב וְלֹא יִזְנוּ אַנְשֵׁי הָאָרֶץ. אֲבָל עִקַּר הַכָּתוּב שֶׁהוּא לָאו שֵׁנִי, וּכְבָר מְנָאוֹ בַּעַל הֲלָכוֹת גְּדוֹלוֹת בְּחֶשְׁבּוֹן הַלָּאוִין, וְהִיא אַזְהָרָה לָאִישׁ הַזּוֹנֶה וְלַבַּת עַצְמָהּ שֶׁלֹּא תִּמְסֹר עַצְמָהּ לְשֵׁם זְנוּת. וּמִכָּאן הוּא שֶׁאָמְרוּ שָׁם בַּבָּרַיְתָא (ת"כ שם ז א), וְכֵן הִיא הַמּוֹסֶרֶת עַצְמָהּ שֶׁלֹּא לְשֵׁם אִישׁוּת. וְטַעַם הַכָּתוּב כִּי בַּעֲבוּר שֶׁהַבַּת בִּרְשׁוּת אָבִיהָ, וְהוּא רַשַּׁאי בִּנְעוּרֶיהָ לְקַדֵּשׁ אוֹתָהּ וּלְהַכְנִיסָהּ לְחֻפָּה, וְהָאוֹנֵס וְהַמְּפַתֶּה אוֹתָהּ נוֹתֵן קְנָסָהּ לְאָבִיהָ, פֵּרֵשׁ הַכָּתוּב שֶׁאֵינֶנּוּ רַשַּׁאי לְמָסְרָהּ לְמִי שֶׁיִּהְיֶה זְנוּת, וְהִזְהִירוֹ מִזֶּה בְּלָאו, וְאַחֲרֵי אַזְהָרַת הָאָב הִזְהִיר גַּם הַזֹּנִים עַצְמָם, הָאִישׁ וְהָאִשָּׁה. וְרַשִׁ"י כָּתַב בְּפָרָשַׁת אֱמֹר אֶל הַכֹּהֲנִים (להלן כא ז), "זוֹנָה" - שֶׁנִּבְעֲלָה בְּעִילַת יִשְׂרָאֵל הָאָסוּר לָהּ, כְּגוֹן חַיָּבֵי כָּרֵתוֹת אוֹ נָתִין אוֹ מַמְזֵר. וְזוֹ הוֹדָאָה מִמֶּנּוּ שֶׁאֵין זְנוּת בִּכְשֵׁרִין, אֶלָּא שֶׁהוּא מְרַבֶּה בָּהּ אַף חַיָּבֵי לָאוִין, וְזֶה דַּעְתּוֹ גַּם בְּפֵרוּשָׁיו בַּגְּמָרָא (יבמות סא). וְגַם זֶה אֵינֶנּוּ נָכוֹן, אֶלָּא מֵחַיָּבֵי כָּרֵתוֹת וְכוּתִי וְעֶבֶד שֶׁאֵין קִדּוּשִׁין בָּהּ הִיא נַעֲשֵׂית זוֹנָה, וְכֹהֵן לוֹקֶה עָלֶיהָ מִשּׁוּם זוֹנָה, אֲבָל מֵחַיָּבֵי לָאוִין - מַמְזֵר וְגֵר וְעַמּוֹנִי וּמוֹאָבִי - אֵינָהּ זוֹנָה וְאֵינוֹ לוֹקֶה עָלֶיהָ, אֶלָּא שֶׁנִּפְסְלָה מִן הַתְּרוּמָה וּמִן הַכְּהֻנָּה, דִּכְתִיב (ויקרא כ"ב:י"ב) "כִּי תִהְיֶה לְאִישׁ זָר", כֵּיוָן שֶׁנִּבְעֲלָה לְפָסוּל לָהּ פְּסוּלָה (יבמות סח), וּמֵחַיָּבֵי לָאוִין שֶׁבַּכְּהֻנָּה נַעֲשֵׂית חֲלָלָה:
@30 **אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ** הָאַזְהָרוֹת בַּשַּׁבָּת רַבּוֹת בַּתּוֹרָה כְּמוֹ בַּעֲבוֹדָה זָרָה, מִפְּנֵי שֶׁגַּם הִיא שְׁקוּלָה כְּנֶגֶד כָּל הַמִּצְוֹת, כִּי מִי שֶׁאֵינוֹ מְשַׁמֵּר אוֹתָהּ מַכְחִישׁ בְּמַעֲשֵׂה בְּרֵאשִׁית וְאֵין לוֹ תּוֹרָה כְּלָל. וּלְרַבּוֹתֵינוּ בָּהֶן מִדְרָשׁ, אָמְרוּ בְּכָאן, יָכוֹל יְהֵא בִּנְיַן בֵּית הַמִּקְדָּשׁ דּוֹחֶה שַׁבָּת, תַּלְמוּד לוֹמַר "אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ וּמִקְדָּשִׁי תִּירָאוּ אֲנִי ה'", בְּתוֹרַת כֹּהֲנִים (פרק ז ו). וְעַל דֶּרֶךְ הָאֱמֶת יְצַוֶּה בַּשַּׁבָּת הַגָּדוֹל וּבַשַּׁבָּת שֶׁהוּא מִקְדָּשׁוֹ, וְצִוָּה בּוֹ שְׁמִירָה וּמוֹרָא, וְהִנֵּה אֵין מְלֶאכֶת בֵּית הַמִּקְדָּשׁ דּוֹחָה הַשַּׁבָּת וְהַמִּקְדָּשׁ. וְאִם תַּשְׂכִּיל תָּבִין:
@32 **מִפְּנֵי שֵׂיבָה תָּקוּם** יָכוֹל מִפְּנֵי זָקֵן אַשְׁמַאי, תַּלְמוּד לוֹמַר "זָקֵן", אֵין זָקֵן אֶלָּא שֶׁקָּנָה חָכְמָה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ט:ל"ב). וּלְשׁוֹן תּוֹרַת כֹּהֲנִים (פרק ז יא), וְהוּא הַשָּׁנוּי בַּגְּמָרָא בְּמַסֶּכֶת קִדּוּשִׁין (לב), תַּלְמוּד לוֹמַר "זָקֵן", אֵין זָקֵן אֶלָּא חָכָם, שֶׁנֶּאֱמַר (במדבר יא טז) "אֶסְפָה לִּי שִׁבְעִים אִישׁ מִזִּקְנֵי יִשְׂרָאֵל". וְרַבִּי יוֹסֵי הַגְּלִילִי אוֹמֵר, אֵין זָקֵן אֶלָּא שֶׁקָּנָה חָכְמָה, שֶׁנֶּאֱמַר (משלי ח כב) "ה' קָנָנִי רֵאשִׁית דַּרְכּוֹ". וְהִנֵּה לְדִבְרֵי שְׁנֵיהֶם אֵין הַמִּצְוָה אֶלָּא בְּחָכָם. וְאוּנְקְלוֹס (תרגום אונקלוס על ויקרא י"ט:ל"ב) אָמַר, "מִן קֳדָם דְּסָבַר בְּאוֹרָיְתָא תָּקוּם וְתֶהְדַּר אַפֵּי סָבָא", וּמַשְׁמָעוּת דְּבָרָיו שֶׁגַּם הוּא סוֹבֵר כֵּן. וְעִם כָּל זֶה, הָעוֹלֶה מִן הַגְּמָרָא לְפִי פְּסַק הַהֲלָכָה אֵינוֹ כֵן, שֶׁהֲרֵי אָמְרוּ (קידושין לב), אִיסִי בֶּן יְהוּדָה אוֹמֵר כָּל שֵׂיבָה בַּמַּשְׁמָע, וְאָמַר רַבִּי יוֹחָנָן (שם לג) הֲלָכָה כְּאִיסִי בֶּן יְהוּדָה. וְהִנֵּה יְצַוֶּה בְּכָל שֵׂיבָה, אֲפִלּוּ עַל אַשְׁמַאי שֶׁהוּא הַבּוּר, וְיַחֲזֹר וִיצַוֶּה עַל הַזָּקֵן שֶׁהוּא הַקּוֹנֶה חָכְמָה, וַאֲפִילּוּ יָנִיק וַחֲכִים. וְיִתָּכֵן שֶׁיִּהְיֶה גַּם כֵּן דַּעַת אוּנְקְלוֹס, אֲבָל יְתַרְגֵּם יָנִיק וַחֲכִים בְּשֵׂיבָה, דַּאֲתָא זָקֵן וְגַלִּי בַּשֵּׂיבָה שֶׁבִּכְלָלָהּ כָּל הַשֵּׂיבוֹת, בֵּין שֵׂיבַת הַתּוֹרָה בֵּין שֵׂיבַת הַיָּמִים:
@40 **לְמַעַן טַמֵּא אֶת מִקְדָּשִׁי** לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ':ג'), אֶת כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא מְקֻדֶּשֶׁת לִי. וּכְבָר רָמַזְתִּי זֶה (רמב"ן על ויקרא י"ח:כ"א) אֵיךְ תִּטְמָא כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא מְקֻדֶּשֶׁת לִשְׁמוֹ הַגָּדוֹל בְּאִישׁ אֶחָד אֲשֶׁר יֶחֱטָא. וּכְבָר רָמְזוּ זֶה בְּמִדְרָשָׁם, שֶׁאָמְרוּ (ברכות לה), כָּל הַנֶּהֱנֶה מִן הָעוֹלָם הַזֶּה בְּלֹא בְּרָכָה כְּאִלּוּ גָּזַל לְהקב"ה וּכְנֶסֶת יִשְׂרָאֵל, שֶׁנֶּאֱמַר (משלי כח כד) "גּוֹזֵל אָבִיו וְאִמּוֹ" וְגוֹ', אֵין אָבִיו אֶלָּא הקב"ה וְאֵין אִמּוֹ אֶלָּא כְּנֶסֶת יִשְׂרָאֵל; "חָבֵר הוּא לְאִישׁ מַשְׁחִית" חָבֵר הוּא לְיָרָבְעָם בֶּן נְבָט שֶׁהֶחְטִיא אֶת יִשְׂרָאֵל לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם. כִּי הַחֵפֶץ בַּיְּצִירָה שֶׁיְּבָרְכוּ עָלֶיהָ לִשְׁמוֹ הַגָּדוֹל, וּמִשָּׁם יִהְיֶה קִיּוּם הָעוֹלָם, וְאִם לֹא יִתְבָּרֵךְ בִּשְׁמוֹ הַגָּדוֹל תִּסְתַּלֵּק הַשְּׁכִינָה מִיִּשְׂרָאֵל, וְכָל שֶׁכֵּן כְּשֶׁיַּקְרִיב הַפְּרִי לַמֹּלֶךְ, שֶׁהוּא מְתַעֵב אֶת גְּאוֹן יַעֲקֹב וּמִשְׁכָּנוֹ. וְזֶה טַעַם "עַם הָאָרֶץ יִרְגְּמֻהוּ בָאָבֶן" (ויקרא כ':ב'), כִּי לֹא אָמַר, מוֹת יוּמָת בָּאֶבֶן יִרְגְּמוּ אוֹתוֹ, כַּאֲשֶׁר אָמַר בְּכֻלָּן, אֶלָּא הִזְכִּיר "עַם הָאָרֶץ", לוֹמַר שֶׁכָּל אַנְשֵׁי הָאָרֶץ כָּל יִשְׂרָאֵל חַיָּבִין לְהַקְדִּים וּלְסָקְלוֹ, כִּי לְכֻלָּם יַזִּיק, כִּי גּוֹרֵם לַשְּׁכִינָה שֶׁתִּסְתַּלֵּק מִיִּשְׂרָאֵל. לְכָךְ תִּרְגֵּם אוּנְקְלוֹס "עַמָּא בֵית יִשְׂרָאֵל", כִּי "הָאָרֶץ" יִרְמֹז לְכָל אֶרֶץ יִשְׂרָאֵל, לֹא לָאָרֶץ אֲשֶׁר הָעוֹבֵד יוֹשֵׁב בָּהּ, וּכְעִנְיָן "כִּי לִי הָאָרֶץ" (ויקרא כ"ה:כ"ג). וְעוֹד תּוּכַל לְהָבִין סוֹדוֹ מִמַּה שֶׁהִזְכִּיר הַכָּתוּב בְּכָרֵת הַמֹּלֶךְ "וַאֲנִי אֶתֵּן אֶת פָּנַי בָּאִישׁ הַהוּא" (כאן), וְכֵן "וְשַׂמְתִּי אֲנִי אֶת פָּנַי" (ויקרא כ':ה'), כִּי שְׁמִי הַגָּדוֹל וְהַנּוֹרָא יַכְרִית אוֹתוֹ. וְלֹא הִזְכִּיר בְּכָרֵת אוֹב וְיִדְּעוֹנִי מִלַּת "אֲנִי" וְלֹא בְּשׁוּם כָּרֵת אַחֵר. וּכְבָר הוֹדַעְתִּי טַעַם זֶה לְכָל מֵבִין:
@42 **לִזְנוֹת אַחֲרֵי הַמֹּלֶךְ** לְרַבּוֹת שְׁאָר עֲבוֹדָה זָרָה שֶׁעֲבָדָהּ בְּכָךְ, וַאֲפִלּוּ אֵין זוֹ דֶּרֶךְ עֲבוֹדָתָהּ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ':ה'). וּכְבָר כָּתַב עוֹד בְּסֵדֶר אַחֲרֵי מוֹת (לעיל יח כא) שֶׁהַמֹּלֶךְ הִיא עֲבוֹדָה זָרָה שֶׁשְּׁמָהּ מֹלֶךְ, וְזוֹ הִיא עֲבוֹדָתָהּ, שֶׁמּוֹסֵר בְּנוֹ לַכּוּמָרִים וְכוּ'. וְכָל זֶה אֵינֶנּוּ עוֹלֶה וּמְתֻקָּן כַּהֹגֶן לְפִי הָעִיּוּן בַּגְּמָרָא (סנהדרין סד), כִּי לְדִבְרֵי הָאוֹמֵר מֹלֶךְ עֲבוֹדָה זָרָה הוּא, אֵין עֲבוֹדָתוֹ שֶׁל אוֹתוֹ עֲבוֹדָה זָרָה בְּהַעֲבָרַת הַבָּנִים לָהּ, שֶׁאִם כֵּן לֹא הֻצְרַךְ הַכָּתוּב לְהַזְכִּיר זֶה כְּלָל, שֶׁהֲרֵי הוּא בְּאַזְהָרַת עוֹבֵד עֲבוֹדָה זָרָה שֶׁבָּאוּ בָּהּ כַּמָּה אַזְהָרוֹת בַּתּוֹרָה כְּלָלִיּוֹת, וְהוּא גַּם כֵּן בִּכְלַל הָעֹנֶשׁ הַנֶּאֱמָר בְּפָרָשַׁת "כִּי יִמָּצֵא בְּקִרְבְּךָ אִישׁ אוֹ אִשָּׁה אֲשֶׁר יַעֲשֶׂה אֶת הָרַע בְּעֵינֵי ה' אֱלֹהֶיךָ לַעֲבֹר בְּרִיתוֹ וַיֵּלֶךְ וַיַּעֲבֹד אֱלֹהִים אֲחֵרִים וַיִּשְׁתַּחוּ לָהֶם" (דברים יז ב ג). אֲבָל עַל כָּרְחֵנוּ נִדְרֹשׁ שֶׁכָּל עִקָּר לֹא בָּא הַכָּתוּב אֶלָּא לְחַיֵּב עַל הָעֲבוֹדָה הַזֹּאת שֶׁל הַעֲבָרַת הַזֶּרַע בְּשֶׁלֹּא כְּדַרְכָּהּ. וְכָךְ אָמְרוּ בַּגְּמָרָא (סנהדרין שם), וּלְמַאן דְּאָמַר מֹלֶךְ עֲבוֹדָה זָרָה הוּא, כָּרֵת דְּמֹלֶךְ לָמָּה לִי, לְמַעֲבִיר בְּנוֹ שֶׁלֹּא כְּדַרְכָּהּ. וְהוּא הַדִּין לְעֹנֶשׁ וְאַזְהָרָה הָאֲמוּרִין בּוֹ, שֶׁלֹּא הֻצְרְכוּ אֶלָּא לְמַעֲבִיר בְּנוֹ שֶׁלֹּא כְּדַרְכָּהּ. וְנִרְאֶה שֶׁלְּפִי הַדַּעַת הַזּוֹ לְשׁוֹן "מֹלֶךְ" אֵינוֹ שֵׁם לְפֶסֶל וְצֶלֶם מְיֻחָד אֶלָּא שֵׁם לְכָל נֶעֱבָד בִּכְלָלָם, כָּל שֶׁתַּמְלִיכֵהוּ וּתְקַבְּלֶנּוּ עָלֶיךָ לֶאֱלוֹהַּ. וְהִנֵּה כְּפִי הַדַּעַת הַזּוֹ יִקְרְאוּ בְּנֵי עַמּוֹן לַשִּׁקּוּץ שֶׁלָּהֶן "מֹלֶךְ" (מלכים א יא ז), כִּי הוּא מַלְכָּם, וְהוּא שֵׁם כּוֹלֵל לְכָל נֶעֱבָד, כִּי הוּא מִלְּשׁוֹן מַלְכוּת. וְלֹא כְּדִבְרֵי הָרַב זַ"ל שֶׁאָמַר שֶׁהִיא ע"ז שֶׁשְּׁמָהּ "מֹלֶךְ" וַעֲבוֹדָתָהּ בְּכָךְ. וְכֵן מַה שֶׁכָּתַב פֹּה שֶׁהֻצְרַךְ "לִזְנוֹת אַחֲרֵי הַמֹּלֶךְ" לְרַבּוֹת שְׁאַר ע"ז שֶׁעֲבָדָהּ בְּכָךְ וַאֲפִלּוּ אֵין זוֹ דֶּרֶךְ עֲבוֹדָתָהּ, גַּם כֵּן אִי אֶפְשָׁר מִן הַטַּעַם שֶׁהִזְכַּרְנוּ, שֶׁכָּל עַצְמוֹ לֹא נֶאֱמַר הַכָּרֵת בַּמֹּלֶךְ אֶלָּא לְחַיְּבוֹ בְּשֶׁאֵין דַּרְכּוֹ, וְכָל ע"ז בַּמַּשְׁמָע. וְלֹא יִתָּכֵן שֶׁתֹּאמַר חִיֵּב הַכָּתוּב כָּרֵת בְּאוֹתָהּ ע"ז שֶׁשְּׁמָהּ מֹלֶךְ בְּמַעֲבִיר לוֹ שֶׁלֹּא כְּדַרְכּוֹ, וְחָזַר וְרִבָּה בּוֹ אַף פְּעוֹר וּמַרְקוּלִיס לְכָרֵת, וְכִי לָמָּה יִצְטָרֵךְ הַכָּתוּב לְכָךְ, מַאי שְׁנָא אוֹתָהּ ע"ז מִשְּׁאָר כָּל ע"ז שֶׁבָּעוֹלָם. וְעוֹד שֶׁאִם כֵּן הָיָה צָרִיךְ לְרַבּוֹת עוֹד מַעֲבִיר בְּנוֹ לִפְעוֹר וּמַרְקוּלִיס בִּסְקִילָה, כְּשֵׁם שֶׁרִבָּה אוֹתוֹ לְכָרֵת. אֶלָּא לֹא הִזְכִּיר הַכָּתוּב מֹלֶךְ כָּל עִקָּר, בֵּין בְּאַזְהָרָה (לעיל יח כא) בֵּין בְּעֹנֶשׁ כָּרֵת וּסְקִילָה (כאן), אֶלָּא בְּמַעֲבִיר בְּנוֹ בְּשֶׁלֹּא כְּדַרְכָּהּ לְכָל ע"ז שֶׁבָּעוֹלָם, וּבֵין שֶׁתֹּאמַר שֶׁהַמֹּלֶךְ הוּא שֵׁם לְכָל ע"ז כְּמוֹ שֶׁפֵּרַשְׁנוּ אוֹ שֶׁתֹּאמַר שֶׁהִיא ע"ז יְדוּעָה שֶׁתִּקָּרֵא כָּךְ, הִזְכִּיר הַכָּתוּב אוֹתָהּ ע"ז בְּשֶׁלֹּא כְּדַרְכָּהּ וְהוּא הַדִּין לְכֻלָּן, שֶׁהַחֹמֶר הַזֶּה הוּא בַּעֲבוּר הָעֲבוֹדָה הַקָּשָׁה הַזּוֹ. וְכֵן מוֹכִיחַ כָּל זֶה בַּגְּמָרָא בְּמַסֶּכֶת סַנְהֶדְרִין (סנהדרין ס"ד) לְפִי הַדַּעַת הַזּוֹ שֶׁכָּתַב הָרַב שֶׁהַמֹּלֶךְ ע"ז הוּא. אֲבָל מִשְׁנָתֵנוּ הִיא שְׁנוּיָה כְּדִבְרֵי הָאוֹמֵר מֹלֶךְ לָאו ע"ז הִיא, כְּלוֹמַר שֶׁאֵינוֹ נֶעֱבָד שֶׁיְּקֻבַּל עֲלֵיהֶם כֶּאֱלוֹהַּ כְּלָל, אֲבָל הוּא כְּמַעֲשֵׂה כִּשּׁוּף, לִדְרֹשׁ בְּעַד הַחַיִּים אֶל הַכֶּלֶב הַמֵּת הַהוּא. וּלְפִי הַדַּעַת הַזּוֹ, הֶעֱבִיר בְּנוֹ לִפְעוֹר אוֹ לְמַרְקוּלִיס פָּטוּר. גַּם דִּבְרֵי רַשִׁ"י בְּפֵרוּשָׁיו בְּסַנְהֶדְרִין כָּךְ הֵם כְּמוֹ שֶׁכָּתַבְנוּ. וְהַבָּרַיְתָא הַשְּׁנוּיָה בְּתוֹרַת כֹּהֲנִים (קדושים י יג), "וְהִכְרַתִּי אֹתוֹ וְאֵת כָּל הַזֹּנִים אַחֲרָיו לִזְנוֹת אַחֲרֵי הַמֹּלֶךְ" לְרַבּוֹת שְׁאָר ע"ז בְּהִכָּרֵת, אֵינוֹ מִיִּתּוּר "לִזְנוֹת אַחֲרֵי הַמֹּלֶךְ" כַּמַּשְׁמַע מִדִּבְרֵי הָרַב, אֲבָל יֹאמַר כִּי הַכָּרֵת הַזֶּה כֻּלּוֹ מְיֻתָּר הוּא, וְנִדְרֹשׁ אוֹתוֹ לִשְׁאָר ע"ז. וְהוּא מַה שֶׁאָמְרוּ בַּגְּמָרָא (סנהדרין סד), שָׁלֹשׁ כָּרֵתוֹת בַּע"ז לָמָּה, אַחַת כְּדַרְכָּהּ; וְאַחַת לְשֶׁלֹּא כְּדַרְכָּהּ, כְּלוֹמַר לְזִבּוּחַ וְקִטּוּר וְנִסּוּךְ וְהִשְׁתַּחֲוָיָה שֶׁנִּתְרַבּוּ שֶׁלֹּא כְּדַרְכָּהּ לְמִיתָה, וּמְחַיֵּב אוֹתָן בְּכָאן בְּהִכָּרֵת; וְאַחַת לַמֹּלֶךְ. וּלְמַאן דְּאָמַר מֹלֶךְ ע"ז הוּא, לְמַעֲבִיר בְּנוֹ שֶׁלֹּא כְּדַרְכָּהּ, כְּלוֹמַר בְּכָל ע"ז שֶׁבָּעוֹלָם כְּמוֹ שֶׁהִזְכַּרְנוּ:
@46 וְטַעַם **כִּי אִישׁ אִישׁ אֲשֶׁר יְקַלֵּל אֶת אָבִיו וְאֶת אִמּוֹ** יַחְזֹר לְרֹאשׁ הַפָּרָשָׁה שֶׁאָמַר "אִישׁ אִמּוֹ וְאָבִיו תִּירָאוּ" (ויקרא י"ט:ג'), וְאָמַר כָּאן כִּי אִישׁ אִישׁ אֲשֶׁר לֹא יִשְׁמַע אֵלַי וִיקַלֵּל אָבִיו וְאִמּוֹ מוֹת יוּמָת. וְעַל דֶּרֶךְ הָאֱמֶת בַּעֲבוּר שֶׁאָמַר (ויקרא כ':ז') "וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדֹשִׁים כִּי אֲנִי ה' אֱלֹהֵיכֶם" וְאָמַר (ויקרא כ':ח') "אֲנִי ה' מְקַדִּשְׁכֶם" כִּי הַשֵּׁם הַנִּכְבָּד הוּא הַמְּקַדֵּשׁ אוֹתָנוּ, כִּי הוּא אָבִינוּ וְגוֹאֲלֵנוּ מֵעוֹלָם הוּא שְׁמוֹ, אִם כֵּן הַמְקַלֵּל אֶת הַמִּשְׁתַּתְּפִין בַּיְּצִירָה חַיָּב מִיתָה. וְזֶה טַעַם מִשְׁפַּט הַנּוֹאֵף וְהַנּוֹאֶפֶת אֲשֶׁר סָמַךְ לְכָאן וְהִקְדִּימוֹ לְכָל הָעֲרָיוֹת, וּכְבָר רָמַזְתִּי זֶה לְמַעְלָה (שמות כ יג). וְהִזְכִּיר הַכָּתוּב קְצָת הָעֲרָיוֹת לְחַיֵּיב בָּהֶם מִיתָה, וְהֵן אֵשֶׁת אִישׁ וְאֵשֶׁת אָב וְהַכַּלָּה וְהַזָּכָר וְאִשָּׁה וְאִמָּהּ (ויקרא כ':י'-י"ד), וְהוּא הַדִּין אִשָּׁה וּבִתָּהּ וּבַת בִּתָּהּ, כִּי הִזְכִּיר קְצָת שְׁאֵר הָאִשָּׁה וְהוּא הַדִּין לְכָל הַנִּזְכָּרִים שָׁם (ויקרא י"ח:י"ז) בָּאַזְהָרָה, וְכָל שֶׁכֵּן שְׁאֵר עַצְמוֹ, בַּת בְּנוֹ וּבַת בִּתּוֹ הַנִּזְכָּרִים (ויקרא י"ח:י'), וְאֵין צָרִיךְ לוֹמַר בִּתּוֹ. וּבְכָל זֶה עוֹד מִדְרָשִׁים לְחַיֵּיב אוֹתָן. וְכֵן הִזְכִּיר חִיּוּב הָרְבִיעָה בְּמִיתָה (ויקרא כ':ט"ו-ט"ז), וְחָזַר וְהִזְכִּיר כָּרֵת אַחֵר בַּנִּדָּה (ויקרא כ':י"ח), לְחַיְּבוֹ בְּהַעֲרָאָה בְּלֹא גְּמַר בִּיאָה, הוּא שֶׁאָמַר "אֶת מְקוֹרָהּ הֶעֱרָה" (ויקרא כ':י"ח), וְכֵן בַּאֲחוֹת אֵם וַאֲחוֹת אָב "כִּי אֶת שְׁאֵרוֹ הֶעֱרָה" (ויקרא כ':י"ט). וְהִזְכִּיר דּוֹדָתוֹ וְכֵן אֵשֶׁת אָחִיו (ויקרא כ':כ'-כ"א), לְחַיְּבָם בַּעֲרִירוּת, בֵּין שֶׁלֹּא הָיוּ לוֹ בָּנִים אוֹ הָיוּ לוֹ. וְהַכָּרֵת הַבָּא בַּאֲחוֹתוֹ (ויקרא כ':י"ז) הוּא מְיֻתָּר, וְנִדְרָשׁ לְרַבּוֹתֵינוּ (מכות יד), לָמָּה יָצָא כָּרֵת בַּאֲחוֹתוֹ וְכוּ'. וְעַל דֶּרֶךְ הַפְּשָׁט הוֹסִיף בְּכָרֵת "לְעֵינֵי בְּנֵי עַמָּם" (ויקרא כ':י"ז), לוֹמַר שֶׁתָּמוּת בַּנֹּעַר נַפְשָׁם, בְּעִנְיָן שֶׁיִּרְאוּ וְיָבִינוּ וְיַשְׂכִּילוּ יַחַד כִּי יַד ה' עָשְׂתָה זֹּאת וּקְדוֹשׁ יִשְׂרָאֵל גְּזָרָהּ. וְטַעַם "עֲוֹנוֹ יִשָּׂא", שֶׁיִּהְיֶה הַחֵטְא הַהוּא דָּבֵק בּוֹ מִן הָעֵת הַהִיא, מַעֲשָׂיו לֹא יַצְלִיחוּ וְרָבְצָה בּוֹ הָאָלָה, כִּי יַכֵּהוּ הַשֵּׁם בְּתַחֲלֻאִים רָעִים עַד הַשְׁמִידוֹ בְּכָרֵת, כְּעִנְיָן שֶׁאָמְרוּ (שבת לג), סִימָן לָעֲבֵרָה הִדְרוֹקָן. וְלֹא הֻצְרַךְ לְהַזְכִּיר חַיָּבֵי הַכָּרֵת הָאֲחֵרִים, כְּגוֹן אִמּוֹ (ויקרא י"ח:ז') וַאֲחוֹת אִשָּׁה (שם יח יח), שֶׁכְּבָר לָמַדְנוּ מִן הַנִּזְכָּרִים כָּל הַצָּרִיךְ:
@54 **וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחֹתוֹ** הִזְכִּיר הַכָּתוּב קִיחָה בַּאֲחוֹתוֹ אע"פ שֶׁאֵין לוֹ בָּהּ קִדּוּשִׁין, בַּעֲבוּר כִּי הָאָח עִם אֲחוֹתוֹ בְּבַיִת אֶחָד שׁוֹכְנִים יַחַד, וְכַאֲשֶׁר יִגְבַּר עָלָיו תַּאֲוָתוֹ יִקָּחֶנָּה וְיִמְשֹׁךְ אוֹתָהּ אֵלָיו, וְאֵינוֹ צָרִיךְ לָבוֹא אֵלֶיהָ כְּבֹא אֶל אִשָּׁה זוֹנָה. וְכֵן דֶּרֶךְ הַכָּתוּב לְהַזְכִּיר קִיחָה בְּכָל הַמִּתְיַחֲדִים, כִּי אִשָּׁה וְאִמָּהּ (ויקרא כ':י"ד) וּבַת בְּנָהּ וּבַת בִּתָּהּ (ויקרא י"ח:י"ז) וְאִשָּׁה וַאֲחוֹתָהּ (שם פסוק יח) וְאֵשֶׁת אָחִיו (ויקרא כ':ט"ז), כֻּלָּן עִמּוֹ בַּבַּיִת. וְכֵן "לֹא יִקַּח אִישׁ אֶת אֵשֶׁת אָבִיו" (דברים כג א). וְאָמַר "וְרָאָה אֶת עֶרְוָתָהּ" דֶּרֶךְ מוּסָר, כִּי הַכָּתוּב יְכַנֶּה בָּעֲרָיוֹת, פַּעַם יִקְרָא הַבְּעִילָה גִּלּוּי עֶרְוָה, כַּאֲשֶׁר יֹאמַר בְּרֻבָּן "לֹא תְגַלֶּה עֶרְוָתָהּ", וְזֶה מִנְהַג הַזֹּנִים שֶׁהֵם מְגַלִּים שׁוּלֶיהָ, כְּעִנְיָן שֶׁנֶּאֱמַר "וְגִלֵּיתִי שׁוּלַיִךְ עַל פָּנָיִךְ" (נחום ג ה); וּפַעַם יְכַנֶּה אוֹתָהּ בִּיאָה, "וּבָא אֵלֶיהָ וּשְׂנֵאָהּ" (דברים כב יג) "לָבֹא עָלֵינוּ" (בראשית יט לא), "וַיָּבֹא אֵלֶיהָ וַתַּהַר לוֹ" (שם לח יח); וּפְעָמִים רַבִּים יִקְרָאֶנָּה שְׁכִיבָה; וּבְכָאן יְכַנֶּה אוֹתָהּ בִּרְאִיָּה, כִּי הָאָח עִם אֲחוֹתוֹ יְשֵׁנִים יַחַד וְאֵין צָרִיךְ לְגַלּוֹת שׁוּלַיִם; וְכֵן יְכַנֶּה אוֹתָהּ בִּידִיעָה, כִּלְשׁוֹן "וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ" (שם ד א), "וְלֹא יָסַף עוֹד לְדַעְתָּה" (שם לח כו), "בְּתוּלָה וְאִישׁ לֹא יְדָעָהּ" (שם כד טז). וְאָמַר "וְהִיא תִרְאֶה אֶת עֶרְוָתוֹ" שֶׁגַּם הִיא חָמְדָה בְּלִבָּהּ עֶרְוָתוֹ וְרָצְתָה לַעֲשׂוֹת כֵּן. וְהִזְכִּיר זֶה בַּאֲחוֹת בִּלְבַד בַּעֲבוּר כִּי כָּל הָעֲרָיוֹת כַּאֲשֶׁר יִקְרַב הָאִישׁ לְגַלּוֹת עֶרְוָתָהּ, לִרְצוֹנָהּ הוּא, כִּי אִם לֹא יִהְיֶה לִרְצוֹנָהּ תִּתְרַחֵק מִמֶּנּוּ וְתִצְעַק, אֲבָל בָּאָח הַיָּשֵׁן עִמָּהּ, אוּלַי שֶׁלֹּא מִדַּעְתָּהּ יַעֲרֶה בָּהּ. עַל כֵּן הִזְכִּיר שֶׁהִיא גַּם הִיא תִּרְאֶה עֶרְוָתוֹ:
@54 וְטַעַם **חֶסֶד הוּא** עַל דַּעַת הַמְפָרְשִׁים - חֶרְפָּה, כִּי הָאֲנָשִׁים כֻּלָּם בְּטִבְעָם יִהְיֶה לָהֶם בֹּשֶׁת בַּחֵטְא הַמְּכֹעָר הַזֶּה. וְהוּא כִּלְשׁוֹן אֲרַמִּית שֶׁתִּרְגֵּם אוּנְקְלוֹס "כִּי חֶרְפָּה הִיא לָנוּ" (בראשית לד יד) - "אֲרֵי חִסּוּדָא הִיא", וְיוֹנָתָן תִּרְגֵּם "וְשַׂמְתִּיהָ חֶרְפָּה" (שמואל א יא ב) - "חִסּוּדָא", וּבִלְשׁוֹן חֲכָמִים (רות רבה ז יא) מִפְּנֵי שֶׁחִסְּדוֹ בָּרַבִּים. וְכֵן "פֶּן יְחַסֶּדְךָ שֹׁמֵעַ" (משלי כה י), יַעֲשֶׂה לְךָ חֶרְפָּה בְּגַלּוֹתְךָ סוֹד אַחֵר. וְטַעַם "וְנִכְרְתוּ לְעֵינֵי בְּנֵי עַמָּם", לֵאמֹר אַתָּה תַּעֲשֶׂה זֶה בַּסֵּתֶר וַה' יְגַלֶּה עֲוֹנְךָ בַּהֲבִיאוֹ עָלֶיךָ עֹנֶשׁ לְעֵינֵי כָּל בְּנֵי עַמְּךָ. וְהִזְכִּיר כֵּן בַּחֵטְא הַנַּעֲשֶׂה בְּחַדְרֵי חֲדָרִים, וְהוּא הַדִּין בְּכָל הַכְּרֵתוֹת כַּאֲשֶׁר הִזְכַּרְתִּי (רמב"ן על ויקרא י"ח:כ"ט). וְטַעַם "עֶרְוַת אֲחֹתוֹ גִּלָּה עֲוֹנוֹ יִשָּׂא", וְאִם גִּלָּה עֶרְוַת אֲחוֹתוֹ בְּאֹנֶס עֲוֹנוֹ יִשָּׂא הוּא לְבַדּוֹ, כְּדִבְרֵי ר"א (אבן עזרא על ויקרא כ':י"ז). וְעַל דַּעְתִּי טַעְמוֹ כִּי עֶרְוַת אֲחֹתוֹ גִּלָּה עֲוֹנוֹ יִשָּׂא כָּל אֶחָד מִן הַנִּזְכָּרִים, כְּמוֹ "כִּי אֶת שְׁאֵרוֹ הֶעֱרָה עֲוֹנָם יִשָּׂאוּ" (ויקרא כ':י"ט). וְהַנָּכוֹן בְּעֵינַי בְּמִלַּת "חֶסֶד" שֶׁהוּא כְּמַשְׁמָעוֹ, וְכֵן דַּעַת רַבּוֹתֵינוּ זַ"ל (ת"כ כאן וסנהדרין נח), יֹאמַר כִּי שְׁאֵר הָאַחִים חֶסֶד הוּא וְאֵין רְאוּיִין לְגִלּוּי עֶרְוָה, כִּי בַּקְּרוֹבִים יַזְכִּיר טַעַם מִפְּנֵי שְׁאֵר הַבָּשָׂר, וּבָאַחִים יַזְכִּיר הַחֶסֶד אֲשֶׁר בֵּינֵיהֶם, וְיִהְיֶה "אִישׁ" מוֹשֵׁךְ עַצְמוֹ וְאַחֵר עִמּוֹ. אוֹ הוּא כְּדֶרֶךְ "וַאֲנִי תְּפִלָּה" (תהלים קט ד), "כִּי חֲמוּדוֹת אָתָּה" (דניאל ט כג), "הִנְנִי אֵלֶיךָ זָדוֹן" (ירמיהו נ לא), שֶׁיֶּחְסַר מֵהֶן מִלַּת "אִישׁ", אוֹ שֶׁיְּכַנֶּה הָאִישׁ בְּתָאֳרוֹ, יֹאמַר, וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחֹתוֹ וְרָאָה אֶת עֶרְוָתָהּ, אִישׁ חֶסֶד הוּא, וְנִכְרְתוּ כִּי עֶרְוַת אֲחֹתוֹ גִּלָּה עֲוֹנוֹ יִשָּׂא. הִזְכִּיר כִּי הָיָה רָאוּי לִהְיוֹתוֹ גֹּמֵל נַפְשׁוֹ אִישׁ חָסֶד, וְהוּא עוֹכֵר שְׁאֵרוֹ אַכְזָרִי, כִּי הָיָה רָאוּי שֶׁיַּעֲשֶׂה עִמָּהּ הַחֶסֶד שֶׁיַּעֲשׂוּ הָאַחִים לְהַשִּׂיאָהּ לְבַעַל, וְהוּא פּוֹגֵם וְעוֹכֵר אוֹתָהּ. וְהַכָּתוּב יִתְלֶה הַסִּרְחוֹן בַּזָּכָר, כְּמוֹ "עֶרְוַת אָחִיו גִּלָּה עֲרִירִים יִהְיוּ" (ויקרא כ':כ"א). וְכֵן עַל דַּעְתִּי "פֶּן יְחַסֶּדְךָ שֹׁמֵעַ" (משלי כה י), יָסִיר מִמְּךָ כָּל חֶסֶד, שֶׁלֹּא שָׁמַרְתָּ חַסְדְּךָ אֶת רֵעֲךָ שֶׁמָּסַר לְךָ סוֹדוֹ, כְּמִלַּת "לְדַשְּׁנוֹ" (שמות כז ג), "וּבְכָל תְּבוּאָתִי תְשָׁרֵשׁ" (איוב לא יב) וְכַיּוֹצֵא בָּהֶן, כִּי רָחוֹק הוּא אֶצְלִי לִהְיוֹת מִלַּת חֶסֶד בִּלְשׁוֹן הַקֹּדֶשׁ מְשַׁמֵּשׁ בַּהֲפוּכִים הָאֵלֶּה, וְהַכְּתוּבִים מְשַׁבְּחִים וּמִתְפַּלְּלִים בְּמִלַּת חֶסֶד. אֲבָל "חִסּוּדָא" בִּלְשׁוֹן אֲרַמִּית לָשׁוֹן אַחֶרֶת, וְגַם אוֹתוֹ הַלָּשׁוֹן מַבְדִּיל בֵּינֵיהֶם, זֶה מְתֻרְגָּם (תיוב"ע) "חִסְדָּא" וְזֶה מְתֻרְגָּם "חִסּוּדָא". וְכָתַב רַבֵּנוּ חֲנַנְאֵל כִּי "חֶסֶד לְאֻמִּים חַטָּאת" (משלי יד לד) לְשׁוֹן חֶרְפָּה. וּלְפִי דַּעְתִּי גַּם זֶה לְשׁוֹן תַּהְפּוּכוֹת, כִּי צְדָקָה וָחֶסֶד נִזְכָּרִים בַּפָּסוּק הַהוּא, וְהֵם הָאַחִים הַתְּאוֹמִים הַנִּזְכָּרִים בְּכָל מָקוֹם, כְּמוֹ "רוֹדֵף צְדָקָה וָחֶסֶד" (שם כא כא), "אֲנִי ה' עֹשֶׂה חֶסֶד מִשְׁפָּט וּצְדָקָה בָּאָרֶץ" (ירמיהו ט כג). אֲבָל פְּשַׁט הַכָּתוּב עַל דַּעְתִּי, צְדָקָה תְּרוֹמֵם גּוֹי כַּאֲשֶׁר יַעֲשֶׂנָּה, וְחֶסֶד לְאֻמִּים חַטָּאת כַּאֲשֶׁר לֹא יַעֲשׂוּהוּ, יֹאמַר כִּי בִּצְדָקָה וּבְחֶסֶד רוֹמְמוּת כָּל גּוֹי וּמִכְשׁוֹלָם, אוֹ יֹאמַר צְדָקָה תְּרוֹמֵם הַגּוֹי הַמְיֻחָד שֶׁיַּעֲשֶׂנָּה, וּלְאֻמִּים רַבִּים חוֹטְאִים בַּחֶסֶד וְאֵינָם עוֹשִׂים אוֹתוֹ. וְדִמְיוֹן הַפָּסוּק הַזֶּה הוּא סָמוּךְ לוֹ (משלי יד לג), "בְּלֵב נָבוֹן תָּנוּחַ חָכְמָה וּבְקֶרֶב כְּסִילִים תִּוָּדֵעַ", שֶׁפֵּרוּשׁוֹ תִּוָּדַע שֶׁאֵינָהּ בְּקִרְבָּם, כִּי כָל רוֹאֵיהֶם יַכִּירוּם בְּמַעֲשֵׂיהֶם כִּי כְּסִילִים הֵם וְאֵין בָּהֶם תְּבוּנָה, וְהֵם שְׁנֵיהֶם בְּשׁוֹלְלוּת הָעִנְיָן:
